function U.now()
return os.clock()
end
function U.json(tb)
local ub,vb=pcall(J.JSONEncode,J,tb)
return ub and vb or YMd[1776]
end
function U.unjson(wb)
local xb,yb=pcall(J.JSONDecode,J,wb)
return xb and yb or nil
end
function U.readJson(zb)
local Ab,Bb=pcall(function()
return isfile(zb)and readfile(zb)or nil
end)
return Ab and Bb and U.unjson(Bb)or nil
end
function U.writeJson(Cb,Db)
pcall(function()
if not isfolder(N.FOLDER)then
makefolder(N.FOLDER)
end
end)
pcall(writefile,Cb,U.json(Db))
end
function U.fmt(Eb)
Eb=tonumber(Eb)or 0
if Eb>=1e6 then
return string.format(YMd[1777],Eb/1e6)
end
if Eb>=1e4 then
return string.format(YMd[1778],Eb/1e3)
end
return tostring(math.floor(Eb+0.5))
end
function U.clamp(Fb,Gb,Hb)
return math.max(Gb,math.min(Hb,Fb))
end
function U.count(Ib)
local Jb=0
for Kb in pairs(Ib or{})do
Jb=Jb+1
end
return Jb
end
function U.list(Lb)
if type(Lb)~=YMd[1779]then
return{}
end
if#Lb>0 then
return Lb
end
local Mb={}
for Nb in pairs(Lb)do
table.insert(Mb,Nb)
end
table.sort(Mb,function(Ob,Pb)
return(tonumber(Ob)or 0)<(tonumber(Pb)or 0)
end)
local Qb={}
for Rb,Sb in ipairs(Mb)do
table.insert(Qb,Lb[Sb])
end
return Qb
end
function U.flat(Tb)
return Vector3 .new(Tb.X,0,Tb.Z)
end
function U.plain(Ub,Vb)
local Wb=type(Ub)
if Wb==YMd[1780]or Wb==YMd[689]or Wb==YMd[1781]then
return Ub
end
if Wb~=YMd[1779]or(Vb or 0)>6 then
return nil
end
local Xb={}
for Yb,Zb in pairs(Ub)do
if type(Yb)==YMd[1780]or type(Yb)==YMd[689]then
Xb[Yb]=U.plain(Zb,(Vb or 0)+1)
end
end
return Xb
end
function F.log(_b,cc,dc)
if _b>(O.logLevel or 1)then
return
end
local ec=string.format(YMd[1782],os.date(YMd[1783]),cc,tostring(dc))
table.insert(R.lines,ec)
if#R.lines>250 then
table.remove(R.lines,1)
end
table.insert(R.pending,ec)
local fc=tostring(dc):lower()
if fc:find(YMd[1784])or fc:find(YMd[1785])or fc:find(YMd[1786])or cc==YMd[1787]then
R.problems=R.problems or{}
table.insert(R.problems,ec)
if#R.problems>30 then
table.remove(R.problems,1)
end
end
if O.logConsole then
print(YMd[1788]..ec)
end
end
function F.status(gc,hc)
Q[gc]=hc
F.statusAt=F.statusAt or{}
F.statusAt[gc]=os.time()
end
function F.flush()
if#R.pending==0 then
return
end
local jc=table.concat(R.pending,YMd[1789])..YMd[1789]
table.clear(R.pending)
pcall(function()
if not isfolder(N.FOLDER)then
makefolder(N.FOLDER)
end
if appendfile and isfile(N.LOGFILE)then
appendfile(N.LOGFILE,jc)
else
writefile(N.LOGFILE,jc)
end
end)
end
task.spawn(function()
while F.alive do
task.wait(3)
F.flush()
end
end)
do
local kc=U.readJson(N.SETTINGS)or{}
if kc.shareChosen~=true then
kc.shareStats=nil
end
if kc.autoTeamChosen~=true then
kc.autoTeam=nil
end
for lc,mc in pairs(N.DEFAULTS)do
if kc[lc]~=nil and type(kc[lc])==type(mc)then
O[lc]=kc[lc]
else
O[lc]=mc
end
end
O.seenVersion=type(kc.seenVersion)==YMd[689]and kc.seenVersion or nil
if kc.griffinWatch==true and kc.snipeUnit==nil then
O.snipeOn,O.snipeUnit=true,YMd[861]
end
if O.pickPortal==YMd[706]then
O.portals,O.pickPortal=false,YMd[704]
end
if O.huntCards==YMd[1790]then
O.huntCards=YMd[1791]
end
O.cfgv=1
if not O.simpleGui then
O.simpleGui=true
if not O.play then
O.master=false
