function kb.weatherStrength(rq)
local sq=kb.fx(rq)
local tq=sq.dmg/sq.cd/sq.hp/sq.speed*(1+(sq.range-1)/2)
for uq,vq in pairs(sq.kinds)do
tq=tq*(1+bb.rogueShare(uq)*vq)
end
if sq.ice>0 then
local wq=bb.rogueShare(YMd[1914])
tq=tq*(wq+(1-wq)/(1-sq.ice+sq.ice/fb.modFactor(YMd[2043])))
end
if sq.fly>0 then
tq=tq*(1-sq.fly*0.5)
end
if sq.noCC then
tq=tq*0.95
end
if sq.shroud then
tq=tq*0.9
end
if sq.zap then
tq=tq*0.85
end
return tq/kb.weatherK(rq)
end
kb.WEATHER_K_MIN,kb.WEATHER_K_MAX,kb.WEATHER_K_RUNS=0.5,4,10
function kb.weatherK(xq)
local yq=xq and type(P.hunt)==YMd[1779]and type(P.hunt.wk)==YMd[1779]and P.hunt.wk[tostring(xq)]or nil
return type(yq)==YMd[1779]and tonumber(yq.k)or 1
end
function kb.weatherLearn()
if bb.withOthers or#game:GetService(YMd[682]):GetPlayers()>1 then
return
end
local zq=bb.huntWeather or kb.weatherNow()
local Aq,Bq=bb.pred,bb.calRun
if not zq or type(Aq)~=YMd[1779]or type(Bq)~=YMd[1779]then
return
end
local function Cq(Dq,Eq)
return type(Dq)==YMd[1779]and tonumber(Dq[Eq]or Dq[tostring(Eq)])or nil
end
local Fq={}
for Gq=2,bb.wave()do
local Hq,Iq=Cq(Bq.alive,Gq),Cq(Aq.aliveAt,Gq)
if Hq and Iq and Hq>0 and Iq>0 then
table.insert(Fq,Hq/Iq)
end
end
if#Fq<3 then
return
end
table.sort(Fq)
local Jq=Fq[math.ceil(#Fq/2)]
P.hunt.wk=type(P.hunt.wk)==YMd[1779]and P.hunt.wk or{}
local Kq=P.hunt.wk[tostring(zq)]
local Lq=math.min(kb.WEATHER_K_RUNS-1,type(Kq)==YMd[1779]and tonumber(Kq.n)or 0)
local Mq=kb.weatherK(zq)
local Nq=math.max(1,Lq)
local Oq=math.exp((Nq*math.log(Mq)+math.log(Mq*Jq))/(Nq+1))
Oq=U.clamp(Oq,kb.WEATHER_K_MIN,kb.WEATHER_K_MAX)
bb.wkWas={w=tostring(zq),old=Kq}
P.hunt.wk[tostring(zq)]={k=Oq,n=(type(Kq)==YMd[1779]and tonumber(Kq.n)or 0)+1,at=os.time()}
F.log(1,YMd[2044],string.format(YMd[2045],tostring(zq),Jq,tostring(zq),Oq,Mq,P.hunt.wk[tostring(zq)].n))
end
