function kb.skinPlan()
local xr,yr=N.session(),N.prof()
local zr=N.data(YMd[1945])or{}
local Ar=(yr.inventory and yr.inventory.unique_items)or yr.unique_items or{}
local Br,Cr={},{kinds={},sell={},wear={},pearls=0,missing={}}
for Dr,Er in pairs(Ar)do
local Fr=type(Er)==YMd[1779]and N.Items[Er.item_id]
if Fr and Fr.item_group==YMd[1945]and Fr._skin_set==kb.SKIN_SET and Fr.usage and zr[Fr.usage.skin_id]then
local Gr=Br[Er.item_id]
if not Gr then
Gr={id=Er.item_id,name=Fr.name,rarity=Fr.rarity,skinId=Fr.usage.skin_id,skin=zr[Fr.usage.skin_id],uuids={}}
Br[Er.item_id]=Gr
table.insert(Cr.kinds,Gr)
end
table.insert(Gr.uuids,Er.uuid or Dr)
end
end
table.sort(Cr.kinds,function(Hr,Ir)
return Hr.name<Ir.name
end)
local Jr=kb.team()
local Kr=xr.profile_data.collection.owned_units
for Lr,Mr in ipairs(Cr.kinds)do
for Nr,Or in pairs(Kr)do
if kb.skinFits(Or.unit_id,Mr.skin)then
Mr.fits=true
break
end
end
local Pr=Mr.rarity==YMd[2073]or Mr.rarity==YMd[2074]
Mr.keep=(Mr.fits or Pr)and 1 or 0
for Qr=Mr.keep+1,#Mr.uuids do
table.insert(Cr.sell,{uuid=Mr.uuids[Qr],name=Mr.name,pearls=kb.SKIN_PRICE[Mr.rarity]or 0})
Cr.pearls=Cr.pearls+(kb.SKIN_PRICE[Mr.rarity]or 0)
end
end
for Rr,Sr in ipairs(Jr)do
local Tr=Sr.skin and Sr.skin._skin_id and zr[Sr.skin._skin_id]
if not(Tr and Tr._skin_set==kb.SKIN_SET)then
for Ur,Vr in pairs(zr)do
if type(Vr)==YMd[1779]and Vr._skin_set==kb.SKIN_SET and kb.skinFits(Sr.unit_id,Vr)then
local Wr=Ur..YMd[2075]
if Br[Wr]then
table.insert(Cr.wear,{uuid=Br[Wr].uuids[1],unit=Sr.uuid,unitName=V.name(Sr.unit_id),name=Br[Wr].name})
else
table.insert(Cr.missing,{item=Wr,unitName=V.name(Sr.unit_id),name=Vr.name,boost=tonumber(Vr._damage_boost)or 0,drop=kb.SKIN_DROP[Vr._skin_rarity]or 0})
end
end
end
end
end
return Cr
end
function kb.starPlan(Xr)
Xr=Xr or kb.skinPlan()
local Yr=N.Items[kb.STAR]or{}
local Zr=tonumber(Yr._mythic_unit_pity)or 400
local as=(N.prof().capsule_pity_data or{})[kb.STAR]or{}
local bs=tonumber(as.opens_since_mythic_unit)or 0
local cs={opened=tonumber(as.total_opens)or 0,left=math.max(1,Zr-bs),units={}}
local ds=tonumber(N.cur(YMd[2070]))or 0
cs.can=math.max(0,math.floor((ds-(tonumber(O.pearlFloor)or 0))/kb.STAR_COST))
local es={}
for fs,gs in pairs(N.session().profile_data.collection.owned_units)do
es[gs.unit_id]=true
local hs=N.Units[gs.unit_id]
if hs and hs.evolved and hs.evolved.from then
es[hs.evolved.from]=true
end
end
for js,ks in pairs(Yr.usage and Yr.usage.possible_rewards or{})do
local ls=ks.unit or ks.item
if ls and N.Units[ls]and N.Units[ls].rarity==YMd[2074]and not es[ls]then
table.insert(cs.units,V.name(ls))
end
end
table.sort(cs.units)
local ms={}
if#Xr.missing>0 then
local ns=Xr.missing[1]
table.insert(ms,string.format(YMd[2076],ns.name,ns.unitName))
end
if#cs.units>0 then
table.insert(ms,string.format(YMd[2077],table.concat(cs.units,YMd[1890])))
end
cs.why=table.concat(ms,YMd[2078])
cs.open= #ms>0 and math.min(cs.can,#cs.units>0 and cs.left or 100)or 0
