for ws,xs in ipairs(qs.wear)do
table.insert(vs,xs.name..YMd[2086]..xs.unitName)
end
table.insert(rs,YMd[2087]..table.concat(vs,YMd[1890])..YMd[2085])
end
for ys,zs in ipairs(qs.missing)do
