else
table.insert(rs,YMd[2091])
end
local Gs,Hs=pcall(kb.starPlan,qs)
if Gs then
table.insert(rs,string.format(YMd[2092],Hs.opened,Hs.left,U.fmt(Hs.left*kb.STAR_COST)))
