end
return table.concat(rs,YMd[1789])
end
function kb.skinTick()
if not(O.skinSmart or O.starOpen)or not(P.live.event and kb.is(P.live.event.level))then
return
end
if(F.req.back.skins or 0)>U.now()then
return
end
local Is=N.session()
local function Js(Ks,Ls,Ms)
local Ns=F.gameSaid(Ls)
ab.pickNote.skins=string.format(YMd[2096],Ks,tostring(Ns or Ms or YMd[2097]))
F.log(1,YMd[2015],ab.pickNote.skins)
F.backoff(YMd[2098],1800)
end
local Os=kb.skinPlan()
if O.skinSmart then
local Ps=Os.wear[1]
if Ps and(F.req.back.skinWear or 0)<=U.now()then
local Qs=jb.slotOf(Ps.unit)
if Qs then
P.str.reequip={uuid=Ps.unit,slot=Qs}
F.saveNow()
F.request(YMd[2099],YMd[2100],Ps.unit)
local Rs=U.now()
while U.now()-Rs<4 and jb.slotOf(Ps.unit)do
task.wait(0.25)
end
end
local Ss=U.now()
local Ts,Us=F.request(YMd[2101],YMd[2039],Ps.uuid,{unit_uuid=Ps.unit})
local function Vs()
local Ws=Is.collection:get_unit_by_uuid(Ps.unit)
return Ws and Ws.skin~=nil
end
while U.now()-Ss<5 and not Vs()do
task.wait(0.25)
end
if Qs then
jb.reequip()
end
if Vs()then
F.log(1,YMd[2015],string.format(YMd[2102],Ps.name,Ps.unitName))
ab.pickNote.skins=nil
Os=kb.skinPlan()
else
local Xs=F.gameSaid(Ss)
ab.pickNote.skins=string.format(YMd[2103],Ps.name,tostring(Xs or Us or YMd[2097]))
F.log(1,YMd[2015],ab.pickNote.skins)
F.backoff(YMd[2101],1800)
end
end
if#Os.sell>0 then
local Ys,Zs={},0
for _s=1,math.min(50,#Os.sell)do
table.insert(Ys,Os.sell[_s].uuid)
Zs=Zs+Os.sell[_s].pearls
end
local ct=tonumber(N.cur(YMd[2070]))or 0
local dt=U.now()
local et,ft=F.request(YMd[2104],YMd[2105],Ys)
while U.now()-dt<5 and(tonumber(N.cur(YMd[2070]))or 0)<=ct do
task.wait(0.25)
end
local gt=(tonumber(N.cur(YMd[2070]))or 0)-ct
if gt<=0 then
return Js(YMd[2106],dt,ft)
end
cb.add(string.format(YMd[2107],#Ys),#Ys,YMd[2098],string.format(YMd[2108],U.fmt(gt)))
ab.pickNote.skins=nil
end
end
if O.starOpen then
local ht=Is.inventory
local function jt()
local kt,lt=pcall(ht.get_number_of_owned_item,ht,kb.STAR)
return kt and tonumber(lt)or 0
end
local mt=U.now()
for nt=1,8 do
if U.now()-mt>15 or not F.alive or F.where~=YMd[1849]then
