while U.now()-qt<5 and jt()<=0 do
task.wait(0.25)
end
if jt()<=0 then
return Js(YMd[2116],qt,xt)
end
cb.add(string.format(YMd[2117],jt()),vt-(tonumber(N.cur(YMd[2070]))or 0),YMd[2118],YMd[2119]..pt.why)
ab.pickNote.skins=nil
else
break
end
end
end
end
