end
end
if nJ then
iJ.step=YMd[2404]
elseif not mJ then
iJ.step,iJ.needCoins=YMd[2405],1
elseif iJ.item and not iJ.haveItem then
iJ.step,iJ.needCoins=YMd[2375],math.max(0,iJ.itemCost-iJ.coins)
