end
for UK=1,math.min(QK or 30,200)do
if MK.infinite then
local VK,WK=pcall(N.LU.Infinite.infinite_amt_scale,UK,MK.ld)
local XK,YK=0,0
for ZK,_K in pairs(MK.configs)do
if type(_K)==YMd[1779]and _K.spawn_tier_normal then
local aL,bL=pcall(N.LU.Infinite.infinite_get_normal_unit_chance,_K,UK)
bL=aL and tonumber(bL)or 0
XK=XK+bL
if RK(ZK)then
YK=YK+bL
end
end
end
if XK>0 then
KK=KK+(VK and tonumber(WK)or 10)*YK/XK
end
else
local cL=MK.list[UK]
for dL,eL in ipairs(U.list(cL and cL.wave))do
if RK(eL.unit)then
KK=KK+(tonumber(eL.amount)or 1)
end
end
end
end
KK=math.floor(KK+0.5)
end)
W._spawns[IK]={n=KK,at=os.time()}
return KK
end
function W.missionValue(fL)
