local lL=kL.quest_info
local mL=lL and lL.quest_class
if mL and mL.class==YMd[2442]and type(mL.unit_ids)==YMd[1779]then
local nL=tonumber(mL.amount)or 0
local oL=nL-(tonumber(kL.quest_progress and kL.quest_progress.amount)or 0)
if oL>0 then
local pL=W.levelSpawns(fL,mL.unit_ids)
if pL>0 then
local qL=tonumber(lL.quest_reward and lL.quest_reward.gem_reward)or 0
for rL,sL in pairs(lL.quest_reward and lL.quest_reward.item or{})do
if type(sL)==YMd[1779]and sL.item_id then
qL=qL+W.itemValue(sL.item_id,tonumber(sL.max_amount or sL.amount or sL.min_amount)or 1)
end
end
hL=hL+qL*math.min(1,pL/oL)
iL=string.format(YMd[2443],tostring(lL.quest_name),U.fmt(nL-oL),U.fmt(nL),U.fmt(math.min(pL,oL)))
end
end
end
end
return hL,iL
