local QL=(PL.inventory and PL.inventory.unique_items)or PL.unique_items or{}
local RL={}
for SL,TL in pairs(QL)do
if type(TL)==YMd[1779]and TL.item_id==OL then
local UL=type(TL._unique_item_data)==YMd[1779]and TL._unique_item_data._unique_portal_data or{}
local VL=type(UL._ctl)==YMd[1779]and UL._ctl or{}
local WL={}
for XL,YL in pairs(type(VL._levelmodifiers)==YMd[1779]and VL._levelmodifiers or{})do
if type(YL)==YMd[1779]and YL.id then
table.insert(WL,tostring(YL.id))
end
end
table.insert(RL,{uuid=TL.uuid or SL,pid=OL,level=UL.level_id,tier=tonumber(UL.portal_depth)or 0,diff=tonumber(UL.difficulty_scale)or 1,reward=tonumber(UL._portal_reward_scale)or 1,lanes=tonumber(UL._lanes),host=tonumber(UL._host_star_remnants)or 0,map=UL._override_map,weak=VL._weak_against or UL._weak_against,strong=VL._strong_against or UL._strong_against,mods=WL})
end
end
table.sort(RL,function(ZL,_L)
