function W.portalMod(aM)
local bM,cM={weak={},strong={},res={}},false
for dM,eM in pairs(type(aM.weak)==YMd[1779]and aM.weak or{})do
local fM=type(eM)==YMd[1779]and eM.damage_type or(type(eM)==YMd[689]and eM)or nil
if fM and fM~=YMd[703]then
cM=true
bM.weak[fM]=W.weakAmp(type(eM)==YMd[1779]and eM.amplification)
end
end
for gM,hM in pairs(type(aM.strong)==YMd[1779]and aM.strong or{})do
local iM=type(hM)==YMd[1779]and hM.damage_type or(type(hM)==YMd[689]and hM)or nil
local jM=type(hM)==YMd[1779]and tonumber(hM.amplification)
if iM and iM~=YMd[703]then
cM=true
if jM and jM<1 then
bM.res[iM]=jM
else
bM.strong[iM]=true
end
end
end
return cM and bM or nil
end
function W.weakAmp(kM)
kM=tonumber(kM)
if not kM then
return 1.5
end
return 1+math.max(0,kM)
end
function W.portalFit(lM,mM)
local nM=W.portalMod(lM)
