local oM,pM=0,0
for qM,rM in ipairs(mM or{})do
if not V.isFarm(rM.id)and not V.allyBuff(rM.id)then
local sM,tM=pcall(V.score,rM.u)
tM=sM and tonumber(tM)or 0
oM=oM+tM
pM=pM+tM*V.elem(rM.id,nM)
end
end
return oM>0 and pM/oM or 1
end
