function jb.gainXp(RQ,SQ)
local TQ,UQ=tonumber(RQ.xp)or 0,jb.xpFor(RQ.unit_id,jb.cap(RQ))
local VQ=math.max(0,UQ-TQ)
if VQ<=0 or(SQ or 0)<=0 then
return 0,0
end
local WQ=math.min(SQ,VQ)
local XQ=jb.base(RQ)
if XQ<=0 then
return 0,WQ
end
return jb.share(RQ.unit_id)*(jb.score(jb.whatIf(RQ,{xp=TQ+WQ}))/XQ-1)*100,WQ
end
