end
function jb.relicWorth(YQ,ZQ)
local _Q=ZQ._unique_item_data and ZQ._unique_item_data._unique_relic_data
if not _Q then
return 0
end
local aR=N.Items[ZQ.item_id]or{}
local bR,cR=V.types(YQ.unit_id)
if aR.main_damage_type and aR.main_damage_type~=YMd[2489]and aR.main_damage_type~=cR then
return 0
end
local dR,eR=0,0
for fR,gR in pairs(_Q._core_damage_type_buffs or{})do
if bR[gR.damage_type]then
dR=dR+(tonumber(gR.mul)or 0)+(tonumber(gR.add_upg)or 0)*0.01+(tonumber(gR.pen)or 0)*0.001
eR=eR+(tonumber(gR.crit)or 0)
end
end
dR=dR+eR*0.5
local hR=V.rows(YQ.unit_id)
local iR=hR and hR[hR.max]
local jR=(iR and tonumber(iR.cd)or 0)*V.mult(YQ,YMd[1944])
for kR,lR in pairs(_Q._unique_relic_effects or{})do
local mR=type(lR.params)==YMd[1779]and lR.params or{}
if lR.id==YMd[2490]then
local nR=math.min(1,(tonumber(mR.extra_damage)or 0)*jR/math.max(1,tonumber(mR.time_interval)or 40))
local oR=V.DRONES and V.DRONES[YQ.unit_id]
if oR and oR.late and jR>0 then
local pR=1/jR
nR=nR*pR/(pR+(tonumber(oR.max)or 0)*(tonumber(oR.late.dmg)or 0)*(tonumber(oR.hits)or 1)/math.max(0.1,tonumber(oR.late.cd)or 4))
end
dR=dR+nR
elseif lR.id==YMd[2491]then
dR=dR+(tonumber(mR.dmg_buff)or 0)*0.25
elseif lR.id==YMd[2492]then
dR=dR+(tonumber(mR.dmg_buff)or 0)*eR
elseif lR.id==YMd[2493]then
if bR.magic then
dR=0
else
dR=dR+(tonumber(mR.dmg_buff)or 0)*0.3
end
elseif lR.id==YMd[2494]then
if bR.water_damage then
dR=dR+0.05
end
end
end
return dR
end
function jb.relicPlan()
local qR=N.session()
if not qR then
return nil
end
local rR=qR.inventory and qR.inventory.inventory_profile_data or{}
local sR={}
for tR,uR in ipairs(rR.unique_items or{})do
if type(uR)==YMd[1779]and uR.uuid and(N.Items[uR.item_id]or{}).item_group==YMd[2495]then
table.insert(sR,uR)
end
end
local vR={}
for wR,xR in ipairs(V.equipped())do
local yR=xR.data and xR.data.rarity
if not V.isFarm(xR.id)and(yR==YMd[2073]or yR==YMd[2074]or yR==YMd[2487]or yR==YMd[2496])then
local zR=jb.share(xR.id)
if not P.str.share[xR.id]then
zR=math.min(zR,0.15)
end
local AR={}
for BR,CR in ipairs(sR)do
local DR=jb.relicWorth(xR.u,CR)*zR*100
if DR>0.01 then
table.insert(AR,{it=CR,w=DR})
end
end
table.sort(AR,function(ER,FR)
if ER.w~=FR.w then
return ER.w>FR.w
end
return ER.it.uuid<FR.it.uuid
end)
local GR,HR={},{}
for IR,JR in ipairs(AR)do
local KR=HR[JR.it.item_id]or 0
if#GR<6 and KR<((N.Items[JR.it.item_id]or{}).unique_equip and 1 or 2)then
HR[JR.it.item_id]=KR+1
table.insert(GR,JR)
end
end
if xR.u._equipped_relic then
local LR=false
for MR,NR in ipairs(GR)do
if NR.it.uuid==xR.u._equipped_relic then
LR=true
end
end
local OR=not LR and qR.inventory:get_item_by_uuid(xR.u._equipped_relic)
if OR then
table.insert(GR,{it=OR,w=jb.relicWorth(xR.u,OR)*zR*100})
end
end
table.insert(vR,{e=xR,share=zR,opts=GR})
end
end
local PR,QR={},-1
local RR,SR,TR={},{},{}
local function UR(VR,WR)
if VR> #vR then
if WR>QR then
QR=WR
PR=table.clone(RR)
end
return
end
local XR=vR[VR]
RR[XR.e.uuid]=nil
UR(VR+1,WR)
for YR,ZR in ipairs(XR.opts)do
local _R=(N.Items[ZR.it.item_id]or{}).unique_equip
if not SR[ZR.it.uuid]and not(_R and TR[ZR.it.item_id])then
SR[ZR.it.uuid]=true
if _R then
TR[ZR.it.item_id]=true
end
RR[XR.e.uuid]=ZR.it.uuid
UR(VR+1,WR+ZR.w+(ZR.it.uuid==XR.e.u._equipped_relic and 0.01 or 0))
RR[XR.e.uuid]=nil
SR[ZR.it.uuid]=nil
if _R then
TR[ZR.it.item_id]=nil
end
end
end
end
UR(1,0)
local aS,bS=0,{}
for cS,dS in ipairs(vR)do
local eS=dS.e.u._equipped_relic and qR.inventory:get_item_by_uuid(dS.e.u._equipped_relic)
local fS=eS and jb.relicWorth(dS.e.u,eS)*dS.share*100 or 0
aS=aS+fS
local gS=PR[dS.e.uuid]and qR.inventory:get_item_by_uuid(PR[dS.e.uuid])
local hS=gS and jb.relicWorth(dS.e.u,gS)*dS.share*100 or 0
table.insert(bS,string.format(YMd[2497],V.name(dS.e.id),eS and(N.Items[eS.item_id]or{}).name or YMd[2084],fS,gS and(N.Items[gS.item_id]or{}).name or YMd[2084],hS))
end
return PR,QR-aS,bS,vR
end
