function jb.xpGuess(TT)
local UT=TT.level and N.Levels[TT.level]
if not UT then
return 0
end
local VT=math.min(9,tonumber(UT.story_world_rank)or tonumber(TT.rank)or 9)
local WT=tonumber(UT.story_level_rank)or 6
local XT=(TT.kind==YMd[1818]and 1.5 or 1)*(VT>5 and 2 or 1)
local YT=2.1564^(VT-1)*(40+10*WT)/XT
if TT.kind==YMd[1798]then
YT=3*30*2.1564^(VT-1)/XT
end
local ZT=VT>=9 and 0.3 or(VT>=7 and 0.5 or 1)
return YT*ZT*6
end
function jb.modeBonus(_T)
