end
local lU=W.rec(eU.key)
lU.xp=lU.xp and(lU.xp+(gU-lU.xp)*0.3)or gU
if gU>0 then
F.log(2,jb.LOG,string.format(YMd[2513],eU.key,U.fmt(gU)))
