function jb.feedPlan(nU)
local oU=V.trait(nU)
local pU=oU==YMd[2514]and 1.5 or 1
local qU=math.max(0,jb.xpFor(nU.unit_id,jb.cap(nU))-(tonumber(nU.xp)or 0))
local rU,sU,tU={},0,0
for uU,vU in ipairs(jb.foodHeld())do
local wU=vU.xp*pU
local xU=math.min(vU.n,math.floor((qU-sU)/math.max(1,wU)))
if xU>0 then
rU[vU.id]=xU
sU=sU+xU*wU
tU=tU+xU
end
end
return{feed=rU,planned=sU,n=tU}
end
function jb.run(yU)
local zU=N.session()
