end
local FU,GU=tonumber(AU.xp)or 0,jb.level(AU)
local HU,IU=F.request(YMd[2508],YMd[2516],yU.uuid,CU)
local JU=U.now()
while U.now()-JU<4 and(tonumber((zU.collection:get_unit_by_uuid(yU.uuid)or AU).xp)or 0)<=FU do
task.wait(0.25)
end
local KU=zU.collection:get_unit_by_uuid(yU.uuid)or AU
local MU=(tonumber(KU.xp)or 0)-FU
if MU>0 then
local NU=jb.level(KU)
local OU=NU>GU and string.format(YMd[2510],GU,NU)or string.format(YMd[2511],GU)
cb.add(string.format(YMd[2517],EU,yU.name),EU,YMd[2518],string.format(YMd[2519],U.fmt(MU),OU))
jb.note(string.format(YMd[2520],yU.name,EU,U.fmt(MU),OU,math.abs(MU-DU)>DU*0.1 and string.format(YMd[2521],U.fmt(DU))or YMd[703]))
else
jb.note(string.format(YMd[2522],yU.name,tostring(HU and IU or YMd[2097])))
F.backoff(YMd[2508],600)
end
end
end
