_V[aW]=true
end
end
local cW,dW=F.request(YMd[1874],YMd[2567],VV.uuid)
task.wait(2)
local eW=XV.collection:get_unit_by_uuid(VV.uuid)
local fW=0
for gW,hW in pairs(XV.profile_data.collection.owned_units)do
if hW.unit_id==VV.to then
fW=fW+1
if not _V[gW]then
if O.fuseXpUnit==VV.uuid then
O.fuseXpUnit,O.fuseXpId=gW,VV.to
