cb.add(YMd[2571]..nW,1,YMd[2572],(WV or YMd[2573])..(#iW>0 and(YMd[2574]..table.concat(iW,YMd[1890]))or YMd[703]))
F.log(1,YMd[2575],nW..YMd[2576]..(WV or YMd[2573])..(#iW>0 and(YMd[2574]..table.concat(iW,YMd[1890]))or YMd[703]))
