VW=bX
break
end
end
end
if not VW.ready then
return
end
local cX={}
for dX,eX in ipairs(V.equipped())do
cX[eX.uuid]=true
end
local fX=ab.evoEats(VW,cX)
if fX then
ab.pickNote.autoEvolve=fX
