ab.FUSE_RANK={Rare=1,Epic=2,Legendary=3}
function ab.xpFodder(lX)
local mX=N.session()
local nX=ab.FUSE_RANK[O.fuseXpRarity]or 2
local oX={[lX.uuid]=true,[O.evolveUnit]=true}
for pX,qX in ipairs(V.equipped())do
oX[qX.uuid]=true
end
for rX,sX in ipairs(P.savedTeam or{})do
oX[sX]=true
end
for tX,uX in ipairs(P.train and P.train.on and P.train.on.base or{})do
oX[uX]=true
end
local vX,wX={},0
for xX,yX in pairs(mX.profile_data.collection.owned_units)do
local zX=N.Units[yX.unit_id]
local AX=zX and ab.FUSE_RANK[zX.rarity]
if AX and AX<=nX and not oX[xX]then
local BX=mX.collection:get_unit_by_uuid(xX)or yX
if not(yX._locked or BX._locked)and not(yX._equipped_relic or BX._equipped_relic)then
local CX,DX=pcall(N.USC.calculate_xp_gain_from_fuse,lX,{BX},mX)
DX=CX and tonumber(DX)or 0
if DX>0 then
table.insert(vX,{uuid=xX,id=yX.unit_id,xp=DX,rarity=zX.rarity})
wX=wX+DX
end
end
end
end
table.sort(vX,function(EX,FX)
if EX.xp~=FX.xp then
return EX.xp<FX.xp
end
return EX.uuid<FX.uuid
end)
local GX=math.max(0,jb.xpFor(lX.unit_id,jb.cap(lX))-(tonumber(lX.xp)or 0))
local HX,IX={},0
for JX,KX in ipairs(vX)do
if IX>=GX then
break
end
table.insert(HX,KX)
IX=IX+KX.xp
end
return HX,IX,GX,wX
end
function ab.fuseXpTarget(LX)
local MX=LX and LX.collection:get_unit_by_uuid(O.fuseXpUnit)
if MX then
if O.fuseXpId~=MX.unit_id then
O.fuseXpId=MX.unit_id
F.saveSoon()
