return MX
end
local NX=LX and N.Units[O.fuseXpId]
local OX=NX and NX.evolve and NX.evolve.evolve_unit
local PX,QX
for RX,SX in pairs(OX and LX.profile_data.collection.owned_units or{})do
if SX.unit_id==OX and(not PX or(tonumber(SX.xp)or 0)>QX)then
PX,QX=RX,tonumber(SX.xp)or 0
end
end
if not PX then
