end
F.log(1,YMd[2015],string.format(YMd[2601],V.name(O.fuseXpId),V.name(OX)))
O.fuseXpUnit,O.fuseXpId=PX,OX
F.saveSoon()
return LX.collection:get_unit_by_uuid(PX)
