function ab.autoFuseXp()
if not O.autoFuseXp or O.fuseXpUnit==YMd[703]then
return
end
local gY=N.session()
local hY=ab.fuseXpTarget(gY)
if not hY then
return
end
local iY=V.name(hY.unit_id)
local jY,kY,lY=ab.xpFodder(hY)
if lY<=0 then
ab.pickNote.autoFuseXp=nil
return
end
if#jY==0 then
ab.pickNote.autoFuseXp=YMd[2610]
return
end
if os.time()-(tonumber(O.fuseXpOnAt)or 0)<30 then
ab.pickNote.autoFuseXp=YMd[2611]
return
end
ab.pickNote.autoFuseXp=nil
if F.req.back.fuseXp and U.now()<F.req.back.fuseXp then
return
end
ab.fuseBatch=ab.fuseBatch or 50
local mY,nY,oY=0,0,{}
while F.alive and mY<10 and not P.pauseAll do
if mY>0 then
local pY,qY,rY=ab.xpFodder(gY.collection:get_unit_by_uuid(O.fuseXpUnit)or hY)
jY,lY={},rY
for sY,tY in ipairs(pY)do
if not oY[tY.uuid]then
table.insert(jY,tY)
end
end
if lY<=0 or#jY==0 then
break
end
end
local uY={}
for vY=1,math.min(ab.fuseBatch,#jY)do
table.insert(uY,jY[vY].uuid)
end
local wY=tonumber((gY.collection:get_unit_by_uuid(O.fuseXpUnit)or hY).xp)or 0
local xY=U.now()
local yY,zY=F.request(YMd[2612],YMd[2613],O.fuseXpUnit,uY)
