break
end
nY=nY+1
task.wait(3.5)
continue
end
while U.now()-xY<5 and(tonumber((gY.collection:get_unit_by_uuid(O.fuseXpUnit)or hY).xp)or 0)<=wY do
task.wait(0.1)
end
local AY=tonumber((gY.collection:get_unit_by_uuid(O.fuseXpUnit)or hY).xp)or 0
if AY>wY then
mY=mY+1
for BY,CY in ipairs(uY)do
oY[CY]=true
end
cb.add(string.format(YMd[2614],#uY,iY),#uY,YMd[2615],string.format(YMd[2616],U.fmt(AY-wY)))
F.log(1,YMd[2015],string.format(YMd[2617],#uY,iY,U.fmt(AY-wY),jb.level(gY.collection:get_unit_by_uuid(O.fuseXpUnit)or hY)))
elseif#uY>20 then
ab.fuseBatch=20
F.log(1,YMd[2015],string.format(YMd[2618],#uY,tostring(F.gameSaid(xY)or(yY and zY)or YMd[2097])))
else
local DY=F.gameSaid(xY)
ab.pickNote.autoFuseXp=YMd[2619]..tostring(DY or(yY and zY)or YMd[2097])..YMd[2620]
F.log(1,YMd[2015],YMd[2621]..tostring(DY or(yY and zY)or YMd[2097]))
F.backoff(YMd[2612],1800)
break
end
end
end
