Xbb.n=(tonumber(Xbb.n)or 0)+1
Xbb.per=Xbb.per and(Xbb.per+(Wbb-Xbb.per)*math.max(0.25,1/Xbb.n))or Wbb
P.portalPay[Vbb]=Xbb
end
local Ybb,Zbb=(N.Items[Rbb.item]or{}).name or Rbb.item,(N.Items[Rbb.portal]or{}).name or Rbb.portal
if Rbb.used then
ab.portalLine(string.format(YMd[2972],os.date(YMd[2973]),Sbb,Ybb,gb.have(Rbb.item),Tbb))
if Rbb.won==false then
F.log(1,YMd[2960],string.format(YMd[2974],W.levelName(W.PORTALS[Rbb.portal].level),Sbb,Ybb,gb.have(Rbb.item),Tbb))
else
Ubb(Rbb.portal,math.max(0,Sbb))
F.log(1,YMd[2960],string.format(YMd[2975],W.levelName(W.PORTALS[Rbb.portal].level),Sbb,Ybb,gb.have(Rbb.item),Tbb))
end
else
local _bb=Tbb-(tonumber(Rbb.held)or 0)
Ubb(YMd[2440]..Rbb.portal,math.max(0,_bb))
F.log(1,YMd[2960],string.format(YMd[2976],W.levelName(W.PORTALS[Rbb.portal].from),_bb,Zbb,Tbb,Sbb>0 and string.format(YMd[2977],Sbb,Ybb)or YMd[703]))
end
W.lastScored=nil
F.saveSoon()
end
function ab.simFresh(acb)
local bcb=P.simRes[acb.key]
local ccb,dcb=W.planUnits(acb)
return bcb and bcb.sig==(dcb or W.teamSig())and os.time()-(bcb.at or 0)<6*3600 or false
end
function W.planUnits(ecb)
local fcb=N.session()
if not fcb then
return nil,nil
end
local gcb,hcb
local icb=P.testTeam
if type(icb)==YMd[1779]and(tonumber(icb.left)or 0)>0 and icb.key==ecb.key and type(icb.uuids)==YMd[1779]then
gcb,hcb=icb.uuids,YMd[2978]
elseif type(P.savedTeam)==YMd[1779]and#P.savedTeam>0 then
gcb,hcb=P.savedTeam,YMd[2979]
end
if not gcb then
return nil,nil
end
local jcb={}
for kcb,lcb in ipairs(gcb)do
local mcb=fcb.collection:get_unit_by_uuid(lcb)
if mcb then
table.insert(jcb,mcb)
end
end
if#jcb~= #gcb then
return nil,nil
end
return jcb,fb.sig(jcb),hcb
end
function ab.relicClash(ncb)
local ocb=N.session()
local pcb={}
for qcb,rcb in ipairs(P.savedTeam or{})do
pcb[rcb]=true
end
local scb={}
for tcb,ucb in ipairs(ncb)do
local vcb=ocb.collection:get_unit_by_uuid(ucb)
local wcb=vcb and vcb._equipped_relic and ocb.inventory:get_item_by_uuid(vcb._equipped_relic)
if wcb and wcb.item_id and(N.Items[wcb.item_id]or{}).unique_equip then
table.insert(scb,{uuid=ucb,u=vcb,kind=wcb.item_id,relic=vcb._equipped_relic,k=(pcb[ucb]and 1e12 or 0)+jb.score(vcb)})
end
end
table.sort(scb,function(xcb,ycb)
if xcb.k~=ycb.k then
return xcb.k>ycb.k
end
return xcb.uuid<ycb.uuid
end)
local zcb={}
for Acb,Bcb in ipairs(scb)do
if zcb[Bcb.kind]then
local Ccb=(N.Items[Bcb.kind]or{}).name or Bcb.kind
local Dcb,Ecb=F.request(YMd[2980],YMd[2500],Bcb.relic)
local Fcb=U.now()
while U.now()-Fcb<3 and Bcb.u._equipped_relic==Bcb.relic do
task.wait(0.25)
end
if Bcb.u._equipped_relic~=Bcb.relic then
P.relicOff[Bcb.uuid]=Bcb.relic
F.log(1,YMd[2525],string.format(YMd[2981],V.name(Bcb.u.unit_id),Ccb,V.name(zcb[Bcb.kind])))
else
F.log(1,YMd[2525],string.format(YMd[2982],V.name(Bcb.u.unit_id),Ccb,tostring(Ecb)))
end
else
zcb[Bcb.kind]=Bcb.u.unit_id
end
end
end
function ab.relicBack()
if O.team and O.teamRelics then
table.clear(P.relicOff)
return
end
local Gcb=N.session()
for Hcb,Icb in pairs(P.relicOff)do
local Jcb=Gcb.collection:get_unit_by_uuid(Hcb)
local Kcb=Gcb.inventory:get_item_by_uuid(Icb)
local Lcb=Kcb and Kcb._unique_item_data and Kcb._unique_item_data._unique_relic_data
if Jcb and Lcb and not Jcb._equipped_relic and not Lcb._equipped_unit_uuid and not jb.slotOf(Hcb)then
local Mcb
for Ncb,Ocb in ipairs(V.equipped())do
local Pcb=Ocb.u._equipped_relic and Gcb.inventory:get_item_by_uuid(Ocb.u._equipped_relic)
if Pcb and Pcb.item_id==Kcb.item_id then
Mcb=Ocb
end
end
if Mcb then
P.str.reequip={uuid=Mcb.uuid,slot=Mcb.slot}
F.saveNow()
F.request(YMd[2099],YMd[2100],Mcb.uuid)
local Qcb=U.now()
while U.now()-Qcb<4 and jb.slotOf(Mcb.uuid)do
task.wait(0.25)
end
end
F.request(YMd[2980],YMd[2039],Icb,{unit_uuid=Hcb})
local Rcb=U.now()
while U.now()-Rcb<3 and Jcb._equipped_relic~=Icb do
task.wait(0.25)
end
if Mcb then
jb.reequip()
end
F.log(1,YMd[2525],string.format(YMd[2983],V.name(Jcb.unit_id),(N.Items[Kcb.item_id]or{}).name or tostring(Kcb.item_id),Jcb._equipped_relic==Icb and YMd[703]or YMd[2984]))
end
P.relicOff[Hcb]=nil
end
end
function ab.equipTeam(Scb,Tcb)
local Ucb={}
for Vcb,Wcb in ipairs(V.equipped())do
Ucb[Wcb.uuid]=true
end
if not P.savedTeam then
local Xcb={}
for Ycb,Zcb in ipairs(V.equipped())do
table.insert(Xcb,Zcb.uuid)
end
P.savedTeam=Xcb
end
local _cb,adb=pcall(ab.relicClash,Scb)
if not _cb then
F.log(1,YMd[2123],YMd[2985]..tostring(adb))
end
local bdb={}
for cdb,ddb in ipairs(Scb)do
bdb[ddb]=true
end
local edb,fdb=false,{}
for gdb=1,4 do
for hdb in pairs(Ucb)do
if not bdb[hdb]then
local idb,jdb=F.request(YMd[2099],YMd[2100],hdb)
table.insert(fdb,string.format(YMd[2986],V.name((N.session().collection:get_unit_by_uuid(hdb)or{}).unit_id or YMd[2053]),tostring(jdb)))
task.wait(0.8)
end
end
for kdb,ldb in ipairs(Scb)do
if not Ucb[ldb]then
local mdb
if gdb>2 then
local ndb={}
for odb,pdb in ipairs(V.equipped())do
ndb[pdb.slot]=true
end
for qdb=1,6 do
if not ndb[qdb]then
mdb=qdb
break
end
end
end
local rdb,sdb
if mdb then
rdb,sdb=F.request(YMd[2523],YMd[2524],ldb,mdb)
else
rdb,sdb=F.request(YMd[2523],YMd[2524],ldb)
end
table.insert(fdb,string.format(YMd[2987],V.name((N.session().collection:get_unit_by_uuid(ldb)or{}).unit_id or YMd[2053]),mdb and(YMd[2988]..mdb)or YMd[703],tostring(rdb),tostring(sdb)))
task.wait(0.8)
end
end
local tdb=U.now()
while U.now()-tdb<3 and not hb.same(hb.team(),Scb)do
task.wait(0.25)
end
edb=hb.same(hb.team(),Scb)
if edb then
break
end
Ucb={}
for udb,vdb in ipairs(V.equipped())do
Ucb[vdb.uuid]=true
end
end
W._sigAt=nil
if edb then
F.log(1,YMd[2525],YMd[2989].. #Scb..YMd[2990]..tostring(Tcb))
else
local wdb={}
for xdb,ydb in ipairs(V.equipped())do
table.insert(wdb,V.name(ydb.id))
end
F.log(1,YMd[2525],YMd[2991]..tostring(Tcb)..YMd[2992]..table.concat(wdb,YMd[1890])..YMd[2993]..table.concat(fdb,YMd[2010]))
if not ab.refilling and#V.equipped()<6 then
ab.refilling=true
local zdb,Adb={},{}
for Bdb,Cdb in ipairs(V.equipped())do
Adb[Cdb.uuid]=true
end
for Ddb,Edb in ipairs(P.savedTeam or{})do
if not Adb[Edb]and N.session().collection:get_unit_by_uuid(Edb)then
table.insert(zdb,Edb)
end
end
local Fdb=0
for Gdb,Hdb in ipairs(zdb)do
if#V.equipped()>=6 then
break
end
F.request(YMd[2523],YMd[2524],Hdb)
task.wait(0.8)
local Idb=U.now()
while U.now()-Idb<3 and#V.equipped()<math.min(6,Fdb+1+(6- #zdb))do
task.wait(0.25)
end
for Jdb,Kdb in ipairs(V.equipped())do
if Kdb.uuid==Hdb then
Fdb=Fdb+1
end
end
end
local Ldb={}
for Mdb,Ndb in ipairs(V.equipped())do
table.insert(Ldb,V.name(Ndb.id))
end
F.log(1,YMd[2525],string.format(YMd[2994],Fdb,table.concat(Ldb,YMd[1890])))
W._sigAt=nil
ab.refilling=nil
end
end
F.saveSoon()
return edb
end
function ab.ownSwap()
local Odb=P.ownSwap
if not Odb then
return
end
local Pdb=F.request(YMd[2796],YMd[2797])
if not Pdb then
return
end
if P.train.on then
hb.home()
end
local Qdb=N.session()
local Rdb=table.clone(P.savedTeam or hb.team())
local Sdb,Tdb
for Udb,Vdb in ipairs(Rdb)do
local Wdb=Qdb.collection:get_unit_by_uuid(Vdb)
if Wdb and Wdb.unit_id==Odb.out then
Sdb=Udb
end
if Wdb and Wdb.unit_id==Odb.into then
Tdb=true
end
end
local Xdb,Ydb
for Zdb,_db in pairs(Qdb.profile_data.collection.owned_units)do
if _db.unit_id==Odb.into and(not Xdb or(tonumber(_db.xp)or 0)>Ydb)then
Xdb,Ydb=Zdb,tonumber(_db.xp)or 0
end
end
if Tdb or not Sdb or not Xdb then
P.ownSwap=nil
F.log(1,YMd[2525],string.format(YMd[2995],V.name(Odb.into),V.name(Odb.out),Tdb and YMd[2996]or not Sdb and YMd[2997]or YMd[2998]))
return F.saveSoon()
end
Rdb[Sdb]=Xdb
local aeb=P.savedTeam
P.savedTeam=nil
if ab.equipTeam(Rdb,string.format(YMd[2999],V.name(Odb.into),V.name(Odb.out)))then
P.savedTeam,P.ownSwap=nil,nil
W.lastScored=nil
if F.notify then
F.notify(YMd[3000],string.format(YMd[3001],V.name(Odb.into),V.name(Odb.out)),YMd[2423])
end
else
P.savedTeam=aeb or P.savedTeam
end
F.saveSoon()
end
function ab.restoreTeam()
if not P.savedTeam then
return false
end
local beb={}
for ceb,deb in ipairs(P.savedTeam)do
if N.session()and N.session().collection:get_unit_by_uuid(deb)then
table.insert(beb,deb)
end
end
P.savedTeam=nil
P.savedTeam=not ab.equipTeam(beb,YMd[3002])and beb or nil
if not P.savedTeam then
local eeb,feb=pcall(ab.relicBack)
if not eeb then
F.log(1,YMd[2123],YMd[3003]..tostring(feb))
end
end
F.saveSoon()
return true
end
ab.LAB={EVERY=3,KINDS={story=true,raid=true,infinite=true},MIN_EVIDENCE=5,AGAIN=24*3600}
function ab.unitEvidence(geb)
local heb=P.learn[geb]
local ieb=heb and tonumber(heb.n)or 0
local jeb=db.hive()
local keb=jeb and type(jeb.units)==YMd[1779]and jeb.units[geb]
if type(keb)==YMd[1779]then
ieb=ieb+(tonumber(keb.matches)or 0)+(tonumber(keb.matches3)or 0)
end
return ieb
end
function ab.unitLabSafe(leb)
if O.unitLab==false or type(leb)~=YMd[1779]or not ab.LAB.KINDS[leb.kind]or leb.first then
return false
end
if P.trial or(P.study and not P.study.done)or(type(P.testTeam)==YMd[1779]and(tonumber(P.testTeam.left)or 0)>0)or(P.train and P.train.on)or ab.partyRole()~=YMd[706]then
return false
end
local meb,neb=pcall(ab.matchOn,leb)
if meb and neb then
return false
end
local oeb=type(P.unitLab)==YMd[1779]and P.unitLab or{}
if oeb.pauseKey==leb.key and os.time()<(tonumber(oeb.pauseUntil)or 0)then
return false
end
local peb=W.rec(leb.key)
local qeb,reb=tonumber(peb.runs)or 0,tonumber(peb.wins)or 0
if leb.kind==YMd[1798]then
local seb,teb=pcall(W.infDaily,N.prof(),leb.level,W.infReach(leb.key))
return qeb>=3 and seb and(tonumber(teb)or 1)<=0
end
return qeb>=5 and(tonumber(peb.streak)or 0)==0 and reb/qeb>=0.9
end
function ab.unitLab(ueb)
if not ab.unitLabSafe(ueb)then
return
end
P.unitLab=type(P.unitLab)==YMd[1779]and P.unitLab or{}
local veb=P.unitLab
veb.tried=type(veb.tried)==YMd[1779]and veb.tried or{}
veb.seen=(tonumber(veb.seen)or 0)+1
if veb.seen%ab.LAB.EVERY~=0 then
return
end
local web=N.session()
local xeb=V.equipped()
if not web or#xeb<2 then
return
end
local yeb={}
for zeb,Aeb in ipairs(xeb)do
yeb[Aeb.uuid]=true
yeb[Aeb.id]=true
end
local Beb,Ceb,Deb
for Eeb,Feb in pairs(web.profile_data.collection.owned_units)do
local Geb=Feb.unit_id
if not yeb[Eeb]and not yeb[Geb]and N.Units[Geb]and not V.isFarm(Geb)and not V.allyBuff(Geb)and os.time()-(tonumber(veb.tried[Geb])or 0)>ab.LAB.AGAIN then
local Heb=ab.unitEvidence(Geb)
if Heb<ab.LAB.MIN_EVIDENCE then
local Ieb=web.collection:get_unit_by_uuid(Eeb)or Feb
local Jeb=jb.score(Ieb)
if Jeb>0 and(not Beb or Heb<Ceb or(Heb==Ceb and Jeb>Deb))then
Beb,Ceb,Deb={uuid=Eeb,id=Geb,u=Ieb},Heb,Jeb
end
end
end
end
if not Beb then
return
end
local Keb,Leb
for Meb,Neb in ipairs(xeb)do
if not V.isFarm(Neb.id)and not V.allyBuff(Neb.id)and Neb.uuid~=O.evolveUnit then
local Oeb=jb.score(Neb.u)
if not Keb or Oeb<Leb then
Keb,Leb=Neb,Oeb
end
end
end
if not Keb then
return
end
veb.tried[Beb.id]=os.time()
local Peb=0
for Qeb in pairs(veb.tried)do
Peb=Peb+1
if Peb>300 then
veb.tried[Qeb]=nil
end
end
local Reb,Seb=fb.levelFor(ueb)
if not Reb then
return
end
local Teb=fb.info(Reb,ueb.key,Seb,ueb.mod or W.ldMod(Reb)or W.levelMod(ueb.level))
local Ueb={}
for Veb,Web in ipairs(xeb)do
table.insert(Ueb,Web.uuid==Keb.uuid and Beb.u or Web.u)
end
local Xeb,Yeb=pcall(fb.run,Teb,fb.teamFrom(Ueb,Teb.map),{hpMul=1.1})
local Zeb=Xeb and type(Yeb)==YMd[1779]and(Yeb.won or(Teb.infinite and(tonumber(Yeb.wave)or 0)>=0.8*W.infReach(ueb.key)))
if not Zeb then
F.log(2,YMd[3004],string.format(YMd[3005],V.name(Beb.id),ueb.label))
return
end
local _eb={}
for afb,bfb in ipairs(xeb)do
table.insert(_eb,bfb.uuid==Keb.uuid and Beb.uuid or bfb.uuid)
end
if ab.equipTeam(_eb,YMd[3006]..V.name(Beb.id))then
veb.now={id=Beb.id,out=Keb.id,key=ueb.key,at=os.time(),ev=Ceb}
F.log(1,YMd[3004],string.format(YMd[3007],V.name(Beb.id),V.name(Keb.id),ueb.label,Ceb))
F.saveNow()
end
end
function ab.unitLabDone(cfb)
local dfb=P.unitLab
local efb=type(dfb)==YMd[1779]and dfb.now
if type(efb)~=YMd[1779]then
return
end
dfb.now,dfb.restore=nil,true
if bb.key~=efb.key then
return
end
local ffb=bb.lastEff and bb.lastEff[efb.id]
dfb.runs=(tonumber(dfb.runs)or 0)+1
dfb.done=type(dfb.done)==YMd[1779]and dfb.done or{}
dfb.done[efb.id]={at=os.time(),eff=ffb,won=cfb and true or false}
dfb.last=efb.id
local gfb=0
for hfb in pairs(dfb.done)do
gfb=gfb+1
if gfb>150 then
dfb.done[hfb]=nil
end
end
if not cfb then
dfb.pauseKey,dfb.pauseUntil=efb.key,os.time()+24*3600
end
F.log(1,YMd[3004],string.format(YMd[3008],V.name(efb.id),cfb and YMd[2244]or YMd[3009],ffb and string.format(YMd[3010],ffb)or YMd[3011]))
end
function ab.unitLabText()
if O.unitLab==false then
return YMd[2546]
end
local ifb=type(P.unitLab)==YMd[1779]and P.unitLab or{}
local jfb=0
for kfb in pairs(type(ifb.done)==YMd[1779]and ifb.done or{})do
jfb=jfb+1
end
if jfb==0 then
return YMd[3012]
end
local lfb=ifb.last and ifb.done and ifb.done[ifb.last]
return string.format(YMd[3013],jfb,jfb==1 and YMd[703]or YMd[1627],lfb and string.format(YMd[3014],V.name(ifb.last),lfb.eff and string.format(YMd[3015],lfb.eff)or YMd[3016])or YMd[703])
end
ab.QUICK_SEARCH=7
function ab.teamFor(mfb,nfb)
if mfb.key==YMd[2219]then
if P.savedTeam then
ab.restoreTeam()
end
return
end
local ofb=N.session()
local pfb=P.testTeam
if pfb and(pfb.left or 0)>0 and pfb.key==mfb.key and type(pfb.uuids)==YMd[1779]then
local qfb=0
for rfb,sfb in ipairs(pfb.uuids)do
if ofb.collection:get_unit_by_uuid(sfb)then
qfb=qfb+1
end
end
if qfb== #pfb.uuids then
if P.train.on then
hb.home()
end
if not hb.same(hb.team(),pfb.uuids)then
ab.equipTeam(pfb.uuids,YMd[3017]..tostring(pfb.label))
end
return
end
end
if O.dailyLoop and mfb.kind==YMd[1960]and type(O.dailyTeam)==YMd[1779]and#O.dailyTeam>0 then
local tfb,ufb={},{}
for vfb,wfb in ipairs(P.savedTeam or hb.team())do
local xfb=ofb.collection:get_unit_by_uuid(wfb)
if xfb then
ufb[xfb.unit_id]=wfb
end
end
for yfb,zfb in ipairs(O.dailyTeam)do
local Afb,Bfb=ufb[zfb],nil
if not Afb then
local Cfb,Dfb=V.isFarm(zfb),V.rows(zfb)
for Efb,Ffb in pairs(ofb.profile_data.collection.owned_units)do
if Ffb.unit_id==zfb then
local Gfb=ofb.collection:get_unit_by_uuid(Ffb.uuid)or Ffb
local Hfb,Ifb
if Cfb then
Hfb,Ifb=pcall(V.farm,Gfb,Dfb and Dfb.max or 0)
else
Hfb,Ifb=pcall(V.score,Gfb)
end
Ifb=Hfb and Ifb or 0
if not Bfb or Ifb>Bfb then
Afb,Bfb=Ffb.uuid,Ifb
end
end
end
end
if Afb then
table.insert(tfb,Afb)
end
end
if#tfb== #O.dailyTeam then
if P.train.on then
hb.home()
end
if not hb.same(hb.team(),tfb)then
ab.equipTeam(tfb,YMd[3018])
end
return
end
F.log(1,YMd[2525],YMd[3019])
end
local Jfb=P.savedTeam or hb.team()
local Kfb={}
for Lfb,Mfb in ipairs(Jfb)do
local Nfb=ofb.collection:get_unit_by_uuid(Mfb)
if Nfb then
table.insert(Kfb,Nfb)
end
end
if#Kfb==0 then
return
end
local Ofb=fb.sig(Kfb)
local Pfb=P.simTeam[mfb.key]
if not(Pfb and Pfb.base==Ofb and os.time()-(tonumber(Pfb.at)or 0)<120)then
F.status(YMd[2543],YMd[3020]..tostring(mfb.label))
fb.memoOn()
local Qfb,Rfb=pcall(fb.plan,mfb,true,nfb or(mfb.kind==YMd[1963]and 45)or 20,Kfb)
fb.memo=nil
if not Qfb then
F.log(1,YMd[2123],YMd[3021]..tostring(Rfb))
end
end
local Sfb=P.simTeam[mfb.key]
local Tfb=Sfb and Sfb.base==Ofb and os.time()-(tonumber(Sfb.at)or 0)<120
local Ufb=(Tfb and Sfb.better and type(Sfb.uuids)==YMd[1779]and#Sfb.uuids>0)and Sfb.uuids or Jfb
local Vfb=P.train.on
if Vfb and not hb.same(Vfb.base or{},Ufb)then
hb.home()
Vfb=nil
end
if not Vfb and not hb.same(hb.team(),Ufb)then
if Ufb==Jfb and P.savedTeam then
ab.restoreTeam()
else
ab.equipTeam(Ufb,(Tfb and Sfb.why)and(Sfb.why..YMd[2125]..tostring(mfb.label))or(YMd[3022]..tostring(mfb.label)))
end
end
end
ab.PARTY={invited={},followAt= -999,noteAt= -999}
function ab.partyRole()
local Wfb=tostring(O.party or YMd[706])
return(Wfb==YMd[3023]or Wfb==YMd[3024])and Wfb or YMd[706]
end
function ab.partyNames()
local Xfb={}
for Yfb in tostring(O.partyNames or YMd[703]):gmatch(YMd[3025])do
