function eb.upgradeGain(Kib,Lib,Mib,Nib,Oib,Pib)
local Qib,Rib=Lib[Mib],Lib[Mib+1]
local Sib=(Qib.cd>0 and Qib.damage/Qib.cd or 0)
local Tib=(Rib.cd>0 and Rib.damage/Rib.cd or 0)*V.aoe(Rib.atk,Rib.range)/math.max(0.3,V.aoe(Qib.atk,Qib.range))
local Uib=Sib>0 and Kib*(Tib/Sib-1)or(Pib or 0)
local Vib=Lib[Mib+2]
if Vib and Mib+1<Lib.max and Vib.cd>0 and Rib.cd>0 and Sib>0 then
local Wib=Kib*((Vib.damage/Vib.cd)/Sib-1)
local Xib=Nib+Vib.cost*Oib
if Wib/Xib>Uib/Nib then
Uib=Uib+(Wib/Xib*Nib-Uib)*0.5
end
end
local Yib=(Rib.range or 0)>(Qib.range or 0)and(1+((Rib.range-Qib.range)/math.max(1,Qib.range)))or 1
return math.max(0,Uib)*Yib
end
function eb.dpsFor(Zib,_ib)
if _ib<=0 then
return 0
end
local ajb={}
for bjb,cjb in ipairs(Zib)do
if not cjb.farm and cjb.gain>0 then
table.insert(ajb,cjb)
end
end
table.sort(ajb,function(djb,ejb)
return djb.gain/djb.cost>ejb.gain/ejb.cost
end)
local fjb,gjb=0,0
for hjb,ijb in ipairs(ajb)do
if _ib<=0 then
break
end
gjb=ijb.gain/ijb.cost
local jjb=math.min(1,_ib/ijb.cost)
fjb=fjb+ijb.gain*jjb
_ib=_ib-ijb.cost*jjb
end
return fjb+math.max(0,_ib)*gjb*0.7
end
function eb.shieldDps(kjb,ljb,mjb,njb,ojb,pjb,qjb)
if(njb or 0)<=0 or(kjb or 0)<=0 or(ojb or 0)<=0 then
return kjb or 0
end
ljb,mjb,pjb=math.max(0.3,ljb or 2),math.max(1,mjb or 1),pjb or 1
local rjb=kjb*pjb*ljb/mjb
return ojb*mjb/((njb/math.max(1,qjb or 1)+math.max(1,ojb/rjb))*ljb)/pjb
end
function eb.shieldGain(sjb,tjb,ujb,vjb,wjb,xjb,yjb,zjb)
local Ajb,Bjb=V.attackInfo(tjb.atk,tjb.range),V.attackInfo(vjb.atk,vjb.range)
local Cjb=eb.shieldDps(sjb,(tonumber(tjb.cd)or 2)*(yjb or 1),Ajb.n,wjb,xjb,zjb,Ajb.hits)
local Djb=eb.shieldDps(ujb,(tonumber(vjb.cd)or 2)*(yjb or 1),Bjb.n,wjb,xjb,zjb,Bjb.hits)
local Ejb=math.max(0,((tonumber(vjb.range)or 0)-(tonumber(tjb.range)or 0))/math.max(1,tonumber(tjb.range)or 1))
return math.max(0,Djb-Cjb)+Cjb*Ejb
end
function eb.shieldWork(Fjb,Gjb,Hjb,Ijb,Jjb,Kjb,Ljb,Mjb,Njb)
if(Ijb or 0)<=0 then
return 0
end
local Ojb=3*Ijb*(Jjb or 1)/math.max(1,Kjb or 20)
if(Hjb or 0)>=Ojb then
return 0
end
return math.max(1,Fjb or 1)*math.max(1,Njb or 1)/math.max(0.3,Gjb or 2)*math.min(Ljb or 0,Mjb or 0)
end
function eb.holdGain(Pjb,Qjb,Rjb,Sjb)
if not Pjb or(Qjb or 0)<=0 then
return 0
end
local Tjb,Ujb=tonumber(Pjb.stun)or 0,tonumber(Pjb.slowTime)or 0
if Tjb<=0 and Ujb<=0 then
return 0
end
local Vjb,Wjb=Tjb>0 and Tjb or Ujb,Tjb>0 and 1 or(tonumber(Pjb.slowPct)or 0.3)
local Xjb=Wjb*Vjb/(Vjb+(tonumber(Pjb.ccCd)or 8))
local Yjb=Xjb/math.max(0.1,1-Xjb)
return Qjb*Yjb*U.clamp(Rjb or 0.5,0,1)*math.min(1,(tonumber(Pjb.n)or 1)/2)/(1+(Sjb or 0))
end
function eb.bleedGain(Zjb,_jb,akb,bkb)
if(Zjb or 0)<=0 then
return 0
end
local ckb=_jb or 0
for dkb,ekb in ipairs(akb or{})do
ckb=math.max(ckb,(tonumber(ekb.hp)or 0)*0.5)
end
return Zjb*ckb*(bkb and 0.5 or 1)
end
function eb.bleedShare(fkb,gkb,hkb,ikb)
if fkb<=0 or not gkb then
return 0
end
if ikb then
