for xpb=1,wpb do
local ypb=fb.enemy(bpb,vpb.k,cpb)
if ypb then
table.insert(epb,ypb)
end
end
tpb=tpb+wpb
end
local zpb=bpb.ld._infinite_bound_level and cpb==bpb.total
if zpb then
local Apb,Bpb={},0
for Cpb,Dpb in pairs(bpb.configs)do
if type(Dpb)==YMd[1779]and tonumber(Dpb.spawn_tier_boss)and(ymb(N.LU.Infinite.infinite_get_boss_unit_chance,Dpb,cpb)or 0)>0 then
local Epb=fb.baseStats(bpb,Cpb)
