local Npb=math.max(1,math.min(6,math.floor(cpb/bpb.bossEvery)))
for Opb,Ppb in pairs(bpb.configs)do
if type(Ppb)==YMd[1779]and tonumber(Ppb.spawn_tier_boss)==Npb then
local Qpb=fb.enemy(bpb,Opb,cpb)
if Qpb then
Qpb.boss=true
table.insert(epb,Qpb)
end
break
end
end
end
if bpb.final and tonumber(bpb.final.wave)==cpb and bpb.final.cfg then
local Rpb=fb.enemy(bpb,bpb.final.cfg,cpb)
if Rpb then
Rpb.boss=true
table.insert(epb,Rpb)
end
end
end
local Spb=bpb.fx and bpb.fx.starfall
local Tpb=Spb and bpb.cfgById and bpb.cfgById.star_golem_1
if Tpb and(tonumber(Spb.perWave)or 0)>0 then
if cpb<=1 then
bpb.starAcc=0
end
bpb.starAcc=(bpb.starAcc or 0)+Spb.perWave
while bpb.starAcc>=1 do
local Upb=fb.enemy(bpb,Tpb,cpb)
if Upb then
local Vpb=tonumber(Spb.hpK)or 1
Upb.hp,Upb.max=Upb.hp*Vpb,Upb.max*Vpb
table.insert(epb,Upb)
