local Xpb=math.max(1,math.floor(#epb*Wpb+0.5))
local Ypb= #epb
if Xpb>Ypb then
for Zpb=1,Xpb-Ypb do
local _pb=epb[((Zpb-1)%Ypb)+1]
table.insert(epb,table.clone(_pb))
end
else
for aqb=1,Ypb-Xpb do
table.remove(epb)
end
