function bb.nearSpot(afc,bfc,cfc)
local dfc,efc=nil,9
for ffc,gfc in ipairs(afc or{})do
local hfc=(gfc.X-bfc)^2+(gfc.Z-cfc)^2
if hfc<=efc then
dfc,efc=gfc,hfc
end
end
return dfc
end
function bb.baseRange(ifc)
local jfc=V.rows(ifc)
local kfc=jfc and jfc[jfc.max]and tonumber(jfc[jfc.max].range)
return kfc or(N.Units[ifc]and tonumber(N.Units[ifc].range))or nil
end
function bb.studyMoves(lfc,mfc)
local nfc=V.rows(lfc.id)
local ofc=V.range(lfc.e.u,nfc.max)*mfc
local pfc=ofc*ofc
local qfc,rfc={},{}
for sfc,tfc in ipairs(lfc.spots or{})do
local ufc,vfc,wfc,xfc,yfc=0,0,0,0,0
for zfc,Afc in ipairs(bb.samples)do
local Bfc,Cfc=Afc.pos.X-tfc.X,Afc.pos.Z-tfc.Z
if Bfc*Bfc+Cfc*Cfc<=pfc then
wfc=wfc+1
local Dfc=math.min(49,math.floor(Afc.prog*50))
if Dfc<25 then
ufc=bit32 .bor(ufc,bit32 .lshift(1,Dfc))
else
vfc=bit32 .bor(vfc,bit32 .lshift(1,Dfc-25))
end
if Afc.prog<=0.3 then
xfc=xfc+1
elseif Afc.prog>=0.7 then
yfc=yfc+1
end
end
end
if wfc>0 then
local Efc=ufc..YMd[1905]..vfc
local Ffc=qfc[Efc]
if not Ffc then
Ffc={p=tfc,lo=ufc,hi=vfc,n=wfc,early=xfc,late=yfc}
qfc[Efc]=Ffc
table.insert(rfc,Ffc)
elseif wfc>Ffc.n then
Ffc.p,Ffc.n,Ffc.early,Ffc.late=tfc,wfc,xfc,yfc
end
end
if sfc%40==0 then
task.wait()
end
end
local Gfc={}
for Hfc,Ifc in ipairs(rfc)do
local Jfc=false
for Kfc,Lfc in ipairs(rfc)do
if Hfc~=Kfc and Lfc.n>=Ifc.n and bit32 .band(Ifc.lo,Lfc.lo)==Ifc.lo and bit32 .band(Ifc.hi,Lfc.hi)==Ifc.hi and(Lfc.lo~=Ifc.lo or Lfc.hi~=Ifc.hi or Lfc.n>Ifc.n)then
Jfc=true
break
end
end
if not Jfc then
table.insert(Gfc,Ifc)
end
if Hfc%40==0 then
task.wait()
end
end
local Mfc,Nfc={},{}
local function Ofc(Pfc)
if Pfc and not Nfc[Pfc]then
Nfc[Pfc]=true
table.insert(Mfc,Pfc)
end
end
table.sort(Gfc,function(Qfc,Rfc)
return Qfc.n>Rfc.n
end)
for Sfc=1,math.min(bb.STUDY_K,#Gfc)do
Ofc(Gfc[Sfc].p)
end
table.sort(Gfc,function(Tfc,Ufc)
return Tfc.early>Ufc.early
end)
Ofc(Gfc[1]and Gfc[1].p)
Ofc(Gfc[2]and Gfc[2].p)
table.sort(Gfc,function(Vfc,Wfc)
return Vfc.late>Wfc.late
end)
Ofc(Gfc[1]and Gfc[1].p)
Ofc(Gfc[2]and Gfc[2].p)
local Xfc=0
for Yfc,Zfc in ipairs(bb.hiveSpots(bb.ld and bb.ld.map))do
if Xfc>=bb.STUDY_SHARED then
break
end
local _fc=false
for agc,bgc in ipairs(type(Zfc.units)==YMd[1779]and Zfc.units or{})do
local cgc=bgc==lfc.id and ofc or((bb.baseRange(bgc)or 0)*mfc)
if bgc==lfc.id or(cgc>0 and math.abs(cgc-ofc)<=0.3*ofc)then
_fc=true
break
end
end
local dgc=_fc and tonumber(Zfc.x)and tonumber(Zfc.z)and bb.nearSpot(lfc.spots,tonumber(Zfc.x),tonumber(Zfc.z))or nil
if dgc and not Nfc[dgc]then
Ofc(dgc)
Xfc=Xfc+1
end
end
return Mfc,#rfc,#Gfc,Xfc
end
function bb.studyRun(egc)
local fgc=U.now()
while F.alive and not(bb.finished or bb.result)and(bb.planning or U.now()-fgc<20)do
task.wait(1)
end
local function ggc()
