end
if not ggc()then
return
end
local hgc,igc,jgc=egc.info,egc.team,egc.base
local kgc=hgc.timeLimit~=nil
local lgc=kgc and 1 or math.max(1,tonumber(egc.hard)or 1)
local mgc={lgc*0.95,lgc*1.05}
local ngc=bb.bookFor(hgc)
local ogc={key=egc.key,label=bb.label(),n=ngc and tonumber(ngc.n)or 0,run=0,timed=kgc,kills=hgc.killScore and true or nil,hp=lgc,at=os.time()}
bb.study=ogc
