pgc[vgc.id]=wgc
qgc,rgc,sgc,tgc=qgc+ #(vgc.spots or{}),rgc+xgc,sgc+ #wgc,tgc+zgc
if not ggc()then
return
end
end
ogc.moves=sgc
F.log(1,YMd[2253],string.format(YMd[3674],ogc.label,qgc,rgc,sgc,tgc>0 and string.format(YMd[3675],tgc)or YMd[703]))
local Agc={}
local function Bgc(Cgc)
return{samples=bb.samples,cache=Agc,spots=Cgc,style=jgc.style,list=jgc.list,hybridHill=jgc.hybridHill}
end
local function Dgc(Egc)
local Fgc=0
for Ggc,Hgc in pairs(Egc)do
local Igc=bb.spotRec(Ggc,Hgc)
if Igc then
Fgc=Fgc+(tonumber(Igc.wins)or 0)*200-((tonumber(Igc.runs)or 0)-(tonumber(Igc.wins)or 0))*1500
end
end
return Fgc
end
local function Jgc(Kgc)
local Lgc,Mgc,Ngc=0,0,0
for Ogc,Pgc in ipairs(mgc)do
local Qgc=os.clock()
local Rgc=fb.runRaw(hgc,igc,{hpMul=Pgc,layout=Bgc(Kgc),bg=true})
Lgc,Mgc,Ngc=Lgc+fb.objective(Rgc),Mgc+(tonumber(Rgc.kills)or 0),Ngc+(tonumber(Rgc.wave)or 0)
task.wait(math.clamp((os.clock()-Qgc)*3,0.25,egc.pauseMax or 1.5))
if not ggc()then
return nil
end
end
ogc.n,ogc.run=ogc.n+1,ogc.run+1
return Lgc/ #mgc*100+Dgc(Kgc),Mgc/ #mgc,Ngc/ #mgc
end
local function Sgc(Tgc)
local Ugc={}
for Vgc,Wgc in pairs(Tgc)do
Ugc[Vgc]=Wgc
end
return Ugc
end
local function Xgc(Ygc,Zgc,_gc)
for ahc,bhc in pairs(Ygc)do
if ahc~=Zgc and(U.flat(bhc)-U.flat(_gc)).Magnitude<4.5 then
return true
end
end
return false
end
local chc={spots=Sgc(jgc.spots)}
chc.s,chc.kills,chc.wave=Jgc(chc.spots)
if not chc.s then
