end
ogc.baseKills,ogc.baseWave=chc.kills,chc.wave
ogc.bestKills,ogc.bestWave=chc.kills,chc.wave
if ngc and ngc.aside==nil then
local dhc,ehc=Sgc(chc.spots),0
for fhc,ghc in ipairs(egc.attackers)do
local hhc=ngc.spots[ghc.id]
local ihc=type(hhc)==YMd[1779]and tonumber(hhc[1])and tonumber(hhc[3])and bb.nearSpot(ghc.spots,tonumber(hhc[1]),tonumber(hhc[3]))or nil
if ihc and ihc~=dhc[ghc.id]and not Xgc(dhc,ghc.id,ihc)then
dhc[ghc.id]=ihc
ehc=ehc+1
end
end
if ehc>0 then
local jhc,khc,lhc=Jgc(dhc)
if not jhc then
return bb.studyEnd(ogc,egc,chc)
end
if jhc>chc.s then
chc={spots=dhc,s=jhc,kills=khc,wave=lhc}
ogc.bestKills,ogc.bestWave=khc,lhc
end
end
end
local mhc,nhc=U.now(),ogc.run
local function ohc(phc)
if not(phc.s and phc.s>chc.s+math.max(50,math.abs(chc.s)*0.005))then
return false
end
chc=phc
ogc.bestKills,ogc.bestWave,ogc.better=phc.kills,phc.wave,(ogc.better or 0)+1
pcall(bb.bookSave,hgc,egc,chc,ogc)
