function bb.validOpen(Shc,Thc)
local Uhc=N.PC.raycast(Shc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not Uhc then
return nil
end
if not N.PC.is_valid_raycast_hit(Uhc.Instance,Thc)then
return nil
end
local Vhc=Uhc.Position
if bb.blockedSpot(Vhc)then
return nil
end
local Whc=(tonumber(Thc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(Whc*2,2.5,Whc*2)
bb.probe.CFrame=CFrame.new(Vhc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return Vhc
end
