bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3*24*3600,0.015,300
function bb.layoutRecFor(xjc,yjc)
local zjc=bb.bookKey(xjc)
P.layoutRec=type(P.layoutRec)==YMd[1779]and P.layoutRec or{}
local Ajc=P.layoutRec[zjc]
if type(Ajc)~=YMd[1779]then
if not yjc then
return nil
end
Ajc={at=os.time()}
P.layoutRec[zjc]=Ajc
if U.count(P.layoutRec)>80 then
local Bjc,Cjc
for Djc,Ejc in pairs(P.layoutRec)do
local Fjc=type(Ejc)==YMd[1779]and tonumber(Ejc.at)or 0
if not Cjc or Fjc<Cjc then
Bjc,Cjc=Djc,Fjc
end
end
P.layoutRec[Bjc]=nil
end
end
return Ajc
end
function bb.layoutAdd(Gjc,Hjc,Ijc,Jjc,Kjc)
Gjc.runs,Gjc.wins=(tonumber(Gjc.runs)or 0)+1,(tonumber(Gjc.wins)or 0)+(Hjc and 1 or 0)
Gjc.sec,Gjc.wave=type(Gjc.sec)==YMd[1779]and Gjc.sec or{},type(Gjc.wave)==YMd[1779]and Gjc.wave or{}
if Hjc and tonumber(Ijc)then
table.insert(Gjc.sec,math.floor(Ijc+0.5))
end
table.insert(Gjc.wave,tonumber(Jjc)or 0)
if tonumber(Kjc)then
Gjc.kills=type(Gjc.kills)==YMd[1779]and Gjc.kills or{}
table.insert(Gjc.kills,math.floor(tonumber(Kjc)))
while#Gjc.kills>bb.LAYOUT_KEEP do
table.remove(Gjc.kills,1)
end
end
while#Gjc.sec>bb.LAYOUT_KEEP do
table.remove(Gjc.sec,1)
end
while#Gjc.wave>bb.LAYOUT_KEEP do
table.remove(Gjc.wave,1)
end
end
function bb.layoutJudge(Ljc,Mjc,Njc,Ojc)
local Pjc,Qjc=tonumber(Ljc and Ljc.runs)or 0,tonumber(Mjc and Mjc.runs)or 0
if Pjc<1 or Qjc<bb.LAYOUT_CONTROL then
return nil
end
if Ojc and type(Ljc.kills)==YMd[1779]and type(Mjc.kills)==YMd[1779]and#Ljc.kills>=1 and#Mjc.kills>=bb.LAYOUT_CONTROL then
local Rjc,Sjc=bb.labMedian(Ljc.kills),bb.labMedian(Mjc.kills)
if Rjc and Sjc and Rjc<Sjc*0.97 and(#Ljc.kills>=2 or Rjc<Sjc*0.85)then
return string.format(YMd[3686],Rjc,Sjc)
end
return nil
end
local Tjc,Ujc=(tonumber(Ljc.wins)or 0)/Pjc,(tonumber(Mjc.wins)or 0)/Qjc
if not Njc and Ujc>=0.5 then
if Tjc+0.25<Ujc and(Pjc>=2 or(Tjc==0 and Ujc>=0.9 and Qjc>=3))then
return string.format(YMd[3687],tonumber(Ljc.wins)or 0,Pjc,Pjc==1 and YMd[703]or YMd[1627],tonumber(Mjc.wins)or 0,Qjc)
end
local Vjc,Wjc=bb.labMedian(Ljc.sec),bb.labMedian(Mjc.sec)
if Vjc and Wjc and Vjc>Wjc*1.10 and(#Ljc.sec>=2 or Vjc>Wjc*1.25)then
return string.format(YMd[3688],math.floor(Vjc/60),Vjc%60,math.floor(Wjc/60),Wjc%60)
end
return nil
end
local Xjc,Yjc=bb.labMedian(Ljc.wave),bb.labMedian(Mjc.wave)
if Xjc and Yjc and Xjc<Yjc-math.max(1,Yjc*0.03)and(Pjc>=2 or Xjc<Yjc*0.85)then
return string.format(YMd[3689],Xjc,Yjc)
end
return nil
end
function bb.layoutResult(Zjc,_jc)
local akc=bb.info
local bkc=bb.layoutSrc
if not(akc and bkc)or bb.labTest or bb.withOthers or bb.fastAlways then
return
end
