bb.CONTROL_WORDS={YMd[3692],YMd[3693],YMd[3694],YMd[3695]}
function bb.controlSpot(lkc,mkc)
if not bb.killZone()then
return nil
end
local nkc=fb.holds
if not nkc(lkc.id)or V.toggleOf(lkc.id)then
return nil
end
local okc,pkc,qkc,rkc=1,0,0,{}
for skc,tkc in ipairs(bb.mine or{})do
local ukc=tkc._stats
local vkc=ukc.id.Value
if ukc:FindFirstChild(YMd[1946])and not V.isFarm(vkc)and not V.allyBuff(vkc)then
local wkc,xkc=U.flat(tkc:GetPivot().Position),ukc.range.Value
if nkc(vkc)and not V.toggleOf(vkc)then
qkc=qkc+1
table.insert(rkc,{p=wkc,r=xkc})
else
for ykc,zkc in ipairs(bb.samples)do
if(U.flat(zkc.pos)-wkc).Magnitude<=xkc then
okc,pkc=math.min(okc,zkc.prog),math.max(pkc,zkc.prog)
end
end
end
end
end
if pkc<=okc then
okc,pkc=0.75,0.98
end
local Akc=(mkc or qkc)+1
local Bkc=({okc,pkc,(okc+pkc)/2,okc-(pkc-okc)/2})[Akc]
if not Bkc then
return nil
end
local Ckc=V.range(lkc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local Dkc={}
for Ekc,Fkc in ipairs(bb.cands)do
local Gkc,Hkc,Ikc=U.flat(Fkc),0,0
for Jkc,Kkc in ipairs(bb.samples)do
if(U.flat(Kkc.pos)-Gkc).Magnitude<=Ckc then
Ikc=Ikc+1
if math.abs(Kkc.prog-Bkc)<=0.05 then
Hkc=Hkc+1
local Lkc=U.flat(Kkc.pos)
for Mkc,Nkc in ipairs(rkc)do
if(Lkc-Nkc.p).Magnitude<=Nkc.r then
Hkc=Hkc-0.5
break
end
end
end
end
end
if Hkc>0 then
table.insert(Dkc,{pos=Fkc,sc=Hkc,cov=Ikc})
end
if Ekc%60==0 then
task.wait()
end
end
table.sort(Dkc,function(Okc,Pkc)
return Okc.sc>Pkc.sc
end)
for Qkc,Rkc in ipairs(Dkc)do
local Skc=bb.valid(Rkc.pos,lkc.data)
if Skc then
F.log(1,YMd[3616],string.format(YMd[3696],V.name(lkc.id),bb.CONTROL_WORDS[Akc],math.floor(Bkc*100+0.5)))
return Skc,Rkc.cov,Bkc
end
if Qkc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(Tkc)
local Ukc,Vkc=fb.holds(Tkc.id)
if not Ukc then
return nil
end
local Wkc,Xkc={},0
for Ykc,Zkc in ipairs(bb.mine or{})do
local _kc=Zkc._stats
local alc=_kc.id.Value
if _kc:FindFirstChild(YMd[1946])and not V.isFarm(alc)and not V.allyBuff(alc)and alc~=Tkc.id then
local blc,clc=pcall(bb.liveDps,Zkc,alc)
clc=blc and tonumber(clc)or 0
if clc>0 then
table.insert(Wkc,{p=U.flat(Zkc:GetPivot().Position),r=_kc.range.Value,d=clc})
Xkc=Xkc+clc
end
end
end
if#Wkc==0 or Xkc<=0 then
