end
local dlc={}
for elc,flc in ipairs(bb.samples)do
local glc,hlc=U.flat(flc.pos),0
for ilc,jlc in ipairs(Wkc)do
if(glc-jlc.p).Magnitude<=jlc.r then
hlc=hlc+jlc.d
end
end
dlc[elc]=hlc/Xkc
end
local klc=V.range(Tkc.u,math.min(tonumber(Vkc)or 0,3,V.rows(Tkc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local llc,mlc,nlc
for olc,plc in ipairs(bb.cands)do
local qlc,rlc,slc=U.flat(plc),0,0
for tlc,ulc in ipairs(bb.samples)do
if(U.flat(ulc.pos)-qlc).Magnitude<=klc then
rlc=rlc+dlc[tlc]
slc=slc+1
end
end
if rlc>0 and(not mlc or rlc>mlc)then
local vlc=bb.valid(plc,Tkc.data)
if vlc then
llc,mlc,nlc=vlc,rlc,slc
end
end
if olc%40==0 then
task.wait()
end
end
if not llc then
return nil
end
bb.holdSaid=bb.holdSaid or{}
if not bb.holdSaid[Tkc.id]then
