local Pnc=U.flat(Knc)
for Qnc,Rnc in ipairs(bb.samples)do
local Snc=(U.flat(Rnc.pos)-Pnc).Magnitude
if Rnc.prog<fnc then
if Snc<=gnc then
Lnc=Lnc-2
end
elseif Snc<=rmc then
Lnc=Lnc+1
end
end
elseif qnc then
Lnc=0
local Tnc=U.flat(Knc)
for Unc,Vnc in ipairs(bb.samples)do
if(U.flat(Vnc.pos)-Tnc).Magnitude<=rmc then
Lnc=Lnc+Vnc.prog*Vnc.prog
end
end
elseif tmc and mnc>0 then
local Wnc=0
for Xnc,Ync in ipairs(lnc)do
local Znc=(U.flat(Ync.pos)-U.flat(Knc)).Magnitude
if Znc<=rmc then
Wnc=Wnc+Ync.dps*(1.1-0.1*Znc/math.max(1,rmc))
end
end
Lnc=Wnc/mnc*100+bb.cover(Knc,rmc,true)*0.05
else
local _nc=bb.cover(Knc,rmc,true,hmc)
if smc then
_nc=bb.cover(Knc,smc)+_nc*0.25
end
Lnc=_nc+(Hnc and 0 or(1-bb.progressAt(Knc))*0.5)
local aoc=0
for boc,coc in ipairs(knc)do
local doc=coc.b.types[jnc]
if doc and(U.flat(coc.pos)-U.flat(Knc)).Magnitude<=coc.range then
aoc=math.max(aoc,math.min(doc,aoc+doc*coc.b.uptime))
end
end
Lnc=Lnc*(1+aoc)
end
if rnc and(U.flat(rnc)-U.flat(Knc)).Magnitude<=snc then
Lnc=Lnc+1e6
end
if tnc and(U.flat(tnc)-U.flat(Knc)).Magnitude<=unc then
Lnc=Lnc+1e6
end
if vnc then
table.insert(vnc,{p=Knc,sc=Lnc})
end
if not Enc or Lnc>Enc then
Dnc,Enc,Fnc=Knc,Lnc,bb.cover(Knc,rmc)
end
end
end
if tmc and#lnc>0 and Dnc then
local eoc=false
for foc,goc in ipairs(lnc)do
if(U.flat(goc.pos)-U.flat(Dnc)).Magnitude<=rmc then
eoc=true
break
end
end
if not eoc then
return nil,0
end
end
if vnc and#vnc>0 then
table.sort(vnc,function(hoc,ioc)
return hoc.sc>ioc.sc
end)
for joc=1,math.min(15,#vnc)do
local koc,loc=vnc[joc].p,0
for moc=0,7 do
local noc=moc*math.pi/4
if bb.valid(koc+Vector3 .new(math.cos(noc),0,math.sin(noc))*5,gmc)then
loc=loc+1
end
if loc>=2 then
break
end
end
if loc>=2 then
return koc,bb.cover(koc,rmc)
end
end
end
return Dnc,Fnc or 0
end
function bb.lookAt(ooc)
local poc,qoc=math.huge,nil
for roc,soc in ipairs(bb.samples)do
local toc=(U.flat(soc.pos)-U.flat(ooc)).Magnitude
if toc<poc then
poc,qoc=toc,soc.pos
end
end
local uoc=qoc and U.flat(qoc-ooc)or Vector3 .new(0,0,-1)
return uoc.Magnitude>0.01 and uoc.Unit or Vector3 .new(0,0,-1)
end
function bb.place(voc,woc)
local xoc=V.isFarm(voc.id)
local yoc,zoc=bb.bestSpot(voc,xoc or(bb.random and V.idol(voc.id)),(bb.trainee~=nil and voc.uuid==bb.trainee)or V.ENTRY[voc.id]==true or(bb.studyEntry==true and voc.id==bb.trialId))
if not yoc then
bb.noSpot[voc.uuid]=(bb.noSpot[voc.uuid]or 0)+1
F.status(YMd[3610],YMd[3699]..V.name(voc.id))
return false
end
local Aoc=bb.money()
local Boc=P.caps[voc.uuid]and bb.count(voc.uuid)or nil
local Coc,Doc=F.request(YMd[3700],YMd[3701],voc.uuid,N.Util.CFramePLV(yoc,bb.lookAt(yoc)))
if Coc and Doc then
if Boc and Boc>=(tonumber(P.caps[voc.uuid])or math.huge)then
F.log(1,YMd[3616],string.format(YMd[3702],V.name(voc.id),tostring(P.caps[voc.uuid])))
P.caps[voc.uuid],P.capsAt[voc.uuid]=nil,nil
F.saveSoon()
end
bb.spent=bb.spent+(voc.data.cost or 0)
table.insert(bb.actions,string.format(YMd[3703],V.name(voc.id)))
F.log(1,YMd[3616],string.format(YMd[3704],V.name(voc.id),bb.spotKey(yoc),zoc,woc))
bb.placeLog=bb.placeLog or{}
table.insert(bb.placeLog,{t=math.floor(U.now()-(bb.startT or U.now())),w=bb.wave(),id=voc.id,x=math.floor(yoc.X),z=math.floor(yoc.Z),cover=math.floor((zoc or 0)+0.5),why=tostring(woc):sub(1,90)})
F.status(YMd[3610],string.format(YMd[3705],V.name(voc.id),woc))
bb.placedAt=bb.placedAt or{}
bb.placedAt[voc.uuid]=(bb.placedAt[voc.uuid]or 0)+1
return true
end
if Aoc>=(voc.data.cost or 0)and bb.random then
bb.placeFail=bb.placeFail or{}
bb.placeFail[voc.uuid]=(bb.placeFail[voc.uuid]or 0)+1
if bb.placeFail[voc.uuid]>=2 then
bb.noSpot[voc.uuid]=3
F.log(1,YMd[3616],string.format(YMd[3706],V.name(voc.id),bb.fieldCount(),bb.FIELD_MAX))
end
end
if Coc and Aoc>=(voc.data.cost or 0)and not bb.random then
local Eoc=bb.spotKey(yoc)
bb.refused[Eoc]=true
bb.refusals=(bb.refusals or 0)+1
bb.unitRefusals[voc.uuid]=(bb.unitRefusals[voc.uuid]or 0)+1
if not bb.crowded()then
local Foc=bb.mapKey()
P.blocked[Foc]=P.blocked[Foc]or{}
if not bb.refusedRun[Eoc]then
P.blocked[Foc][Eoc]=(tonumber(P.blocked[Foc][Eoc])or 0)+1
bb.refusedRun[Eoc]=true
end
if bb.unitRefusals[voc.uuid]>=3 then
local Goc=math.max(1,bb.count(voc.uuid))
if P.caps[voc.uuid]~=Goc or not V.learnedCap(voc.uuid)then
P.caps[voc.uuid],P.capsAt[voc.uuid]=Goc,os.time()
F.log(1,YMd[3616],string.format(YMd[3707],V.name(voc.id),Goc))
end
end
elseif bb.unitRefusals[voc.uuid]>=3 and(bb.noSpot[voc.uuid]or 0)<3 then
bb.noSpot[voc.uuid]=3
F.log(1,YMd[3616],string.format(YMd[3708],V.name(voc.id)))
end
if bb.refusals>=bb.REFUSE_FREE then
if not bb.placePause then
F.log(1,YMd[3616],string.format(YMd[3709],bb.refusals,bb.REFUSE_PAUSE))
end
bb.placePause=U.now()+bb.REFUSE_PAUSE
end
F.log(2,YMd[3616],YMd[3710]..Eoc..YMd[2422]..V.name(voc.id))
F.saveSoon()
end
return false
end
function bb.crowded()
if bb.withOthers then
return true
end
return#game:GetService(YMd[682]):GetPlayers()>1
end
bb.REFUSE_FREE,bb.REFUSE_PAUSE=10,20
function bb.placePaused()
return bb.placePause~=nil and U.now()<bb.placePause
end
function bb.count(Hoc)
local Ioc=0
for Joc,Koc in ipairs({workspace._UNITS,workspace:FindFirstChild(YMd[3546])})do
if Koc then
for Loc,Moc in ipairs(Koc:GetChildren())do
local Noc=Moc:FindFirstChild(YMd[1841])
if Noc and Noc:FindFirstChild(YMd[3676])and Noc.player.Value==M and Noc.uuid.Value==Hoc then
Ioc=Ioc+1
end
end
end
end
return Ioc
end
function bb.measure()
local Ooc,Poc=bb.calRun,bb.info
if not(Ooc and Poc)then
return
end
pcall(bb.sampleHelpers)
local Qoc=U.now()
local Roc=bb.wave()
local Soc=bb.money()
if not Ooc.start and Soc>0 and#bb.mine==0 then
Ooc.start=Soc
end
if Roc~=Ooc.lastW then
if bb.trialId and Roc>0 then
bb.trialTrace=bb.trialTrace or{}
local Toc,Uoc,Voc,Woc=0,{},0,0
for Xoc,Yoc in ipairs(bb.mine)do
local Zoc=Yoc._stats
if Zoc.id.Value==bb.trialId then
Toc=Toc+1
table.insert(Uoc,tostring(Zoc.upgrade.Value))
elseif not V.isFarm(Zoc.id.Value)then
Woc=Woc+1
end
end
pcall(bb.sampleHelpers,true)
for _oc,apc in pairs(bb.ownDealt)do
if apc.id==bb.trialId then
Voc=Voc+apc.v
end
end
local bpc=0
for cpc,dpc in pairs(bb.helperDealt)do
if dpc.owner==bb.trialId then
bpc=bpc+dpc.v
end
end
table.insert(bb.trialTrace,string.format(YMd[3711],Roc,Qoc-(bb.startT or Qoc),Soc,table.concat(Uoc,YMd[2484]),Woc,Voc+bpc,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[Roc-1]or 0,bb.teamDps or 0))
end
if Ooc.lastW and Ooc.lastW>0 and Ooc.lastWT then
table.insert(Ooc.waveSec,Qoc-Ooc.lastWT)
end
if Ooc.paidT and Roc>0 and Qoc-Ooc.paidT<15 then
table.insert(Ooc.skip,Qoc-Ooc.paidT)
end
Ooc.paidT=nil
if Roc>0 then
Ooc.alive[tostring(Roc)]=bb.hpAliveRaw or 0
end
Ooc.lastW,Ooc.lastWT=Roc,Qoc
end
local epc=workspace:FindFirstChild(YMd[3712])
if epc and Roc>0 then
Ooc.timer[tostring(Roc)]=math.max(Ooc.timer[tostring(Roc)]or 0,tonumber(epc.Value)or 0)
end
local fpc=Soc-(bb.lastMoneyR or Soc)
bb.lastMoneyR=Soc
bb.incomeLog=bb.incomeLog or{}
if fpc>0 then
table.insert(bb.incomeLog,{t=Qoc,y=fpc})
end
while bb.incomeLog[1]and Qoc-bb.incomeLog[1].t>30 do
table.remove(bb.incomeLog,1)
end
local gpc=0
for hpc,ipc in ipairs(bb.incomeLog)do
gpc=gpc+ipc.y
end
local jpc=math.min(30,Qoc-(bb.startT or Qoc))
bb.incomeRate=jpc>=8 and gpc/jpc or nil
for kpc,lpc in ipairs(bb.enemies)do
local mpc=lpc.m
local npc=bb.track[mpc]
if not npc then
local opc=mpc._stats
local ppc=mpc:FindFirstChildOfClass(YMd[3532])
local qpc=Poc.cfgById[opc.id.Value]
local rpc=qpc and fb.baseStats(Poc,qpc)
if ppc and rpc and Roc>0 then
local spc=rpc*Poc.hpRaw*fb.waveScale(Poc,Roc,Poc.list[Roc])
if spc>0 and ppc.MaxHealth>0 then
table.insert(Ooc.hp,ppc.MaxHealth/spc)
end
end
bb.track[mpc]={t=Qoc,p=lpc.prog,sp=(opc:FindFirstChild(YMd[3713])and tonumber(opc.speed.Value))or 1}
if ppc and ppc.MaxHealth>0 then
bb.enemyHpSum=(bb.enemyHpSum or 0)+ppc.MaxHealth
end
if Roc>0 then
Ooc.spawn[tostring(Roc)]=(Ooc.spawn[tostring(Roc)]or 0)+1
Ooc.spawnLast[tostring(Roc)]=Qoc-(Ooc.lastWT or Qoc)
end
elseif not npc.done and Qoc-npc.t>=15 then
npc.done=true
local tpc=(lpc.prog-npc.p)/(Qoc-npc.t)/math.max(0.1,npc.sp)
if tpc>0.001 and lpc.prog<0.95 then
table.insert(Ooc.walk,tpc)
end
end
end
local upc=0
for vpc,wpc in ipairs(bb.mine)do
local xpc=wpc._stats:FindFirstChild(YMd[3714])
if xpc then
upc=upc+xpc.Value
end
end
Ooc.potSum=Ooc.potSum or 0
if Ooc.lastDealtT then
local ypc=Qoc-Ooc.lastDealtT
local zpc=0
Ooc.potBy=Ooc.potBy or{}
for Apc,Bpc in ipairs(bb.mine)do
local Cpc=Bpc._stats
local Dpc=Cpc.id.Value
if not V.isFarm(Dpc)and Cpc:FindFirstChild(YMd[3715])and Cpc.target.Value~=nil then
local Epc,Fpc=pcall(bb.liveDps,Bpc,Dpc)
if Epc and Fpc then
zpc=zpc+Fpc*ypc
local Gpc=Fpc/math.max(0.5,V.nudge(Dpc))
local Hpc,Ipc=pcall(function()
return V.passive(Dpc).mark
end)
if Hpc and Ipc and Cpc:FindFirstChild(YMd[1943])then
Gpc=Gpc+(tonumber(Ipc.dot)or 0)*Cpc.damage.Value
end
Ooc.potBy[Dpc]=(Ooc.potBy[Dpc]or 0)+Gpc*ypc
end
end
end
Ooc.potWin=(Ooc.potWin or 0)+zpc
if Qoc-(Ooc.winT or Qoc)>=5 then
local Jpc=upc-(Ooc.winDealt or upc)
if Ooc.potWin>0 and Jpc>=0 then
Ooc.dealtSum=(Ooc.dealtSum or 0)+Jpc
Ooc.potSum=Ooc.potSum+Ooc.potWin
end
Ooc.winT,Ooc.winDealt,Ooc.potWin=Qoc,upc,0
end
end
if not Ooc.winT then
Ooc.winT,Ooc.winDealt=Qoc,upc
end
Ooc.lastDealtT=Qoc
if Roc~=Ooc.dpsW and Roc>0 then
Ooc.dpsAt[tostring(Roc)]=bb.teamDps or 0
Ooc.dpsW=Roc
end
local Kpc=math.min(1,Qoc-(Ooc.densT or Qoc))
Ooc.densT=Qoc
for Lpc,Mpc in ipairs(bb.enemies)do
local Npc=math.min(fb.BINS,math.floor(Mpc.prog*fb.BINS)+1)
Ooc.dens[Npc]=(Ooc.dens[Npc]or 0)+Kpc
end
local Opc=workspace._BASES.player:FindFirstChild(YMd[3716])
local Ppc=Opc and Opc:FindFirstChild(YMd[3717])
local Qpc=Ppc and Ppc:FindFirstChildOfClass(YMd[3532])
if Qpc then
Ooc.baseHp=math.max(Ooc.baseHp or 0,Qpc.MaxHealth)
local Rpc=0
for Spc,Tpc in ipairs(bb.enemies)do
if Tpc.prog>=0.97 then
local Upc=Tpc.m:FindFirstChildOfClass(YMd[3532])
Rpc=Rpc+(Upc and Upc.MaxHealth or Tpc.hp)
end
end
if Ooc.lastBase and Qpc.Health<Ooc.lastBase and Rpc>0 and Ooc.lastBaseT then
table.insert(Ooc.baseRel,(Ooc.lastBase-Qpc.Health)/math.max(0.1,Qoc-Ooc.lastBaseT)/Rpc)
end
Ooc.lastBase,Ooc.lastBaseT=Qpc.Health,Qoc
end
end
function bb.recordMap()
local Vpc=bb.mapKey()
local Wpc=P.maps[Vpc]
if Wpc and Wpc.v==1 and Wpc.laneV and(Wpc.densN or 0)==(Wpc.binsDensN or 0)then
return
end
if Wpc and Wpc.v==1 and Wpc.laneV and(Wpc.densN or 0)>5 and(Wpc.binsDensN or 0)>=5 then
return
end
local Xpc={override_hitbox_radius=1.75}
local Ypc={hill_unit=true,override_hitbox_radius=1.75}
local Zpc,_pc={},false
for aqc,bqc in ipairs(bb.cands)do
local cqc=bb.valid(bqc,Xpc,true)
if cqc then
table.insert(Zpc,cqc)
end
if not _pc and bb.valid(bqc,Ypc,true)then
_pc=true
end
if aqc%30==0 then
task.wait()
end
end
local dqc,eqc={},{}
local fqc=fb.laneList(bb.samples)
for gqc=5,60,5 do
local hqc,iqc
for jqc,kqc in ipairs(Zpc)do
local lqc=bb.cover(kqc,gqc,true)
if not iqc or lqc>iqc then
hqc,iqc=kqc,lqc
end
end
if hqc then
local mqc,nqc={},{}
for oqc=1,fb.BINS do
mqc[oqc]=YMd[3351]
end
for pqc,qqc in ipairs(fqc or{})do
nqc[qqc]={}
for rqc=1,fb.BINS do
nqc[qqc][rqc]=YMd[3351]
end
end
local sqc=U.flat(hqc)
for tqc,uqc in ipairs(bb.samples)do
if(U.flat(uqc.pos)-sqc).Magnitude<=gqc then
local vqc=math.min(fb.BINS,math.floor(uqc.prog*fb.BINS)+1)
mqc[vqc]=YMd[1947]
if nqc[tostring(uqc.lane)]then
nqc[tostring(uqc.lane)][vqc]=YMd[1947]
end
end
end
dqc[tostring(gqc)]=table.concat(mqc)
if fqc then
eqc[tostring(gqc)]={}
for wqc,xqc in pairs(nqc)do
eqc[tostring(gqc)][wqc]=table.concat(xqc)
end
end
end
task.wait()
end
local yqc=P.maps[Vpc]or{}
P.maps[Vpc]={v=1,laneV=1,bins=dqc,binsL=fqc and eqc or nil,lanes=fqc,hill=_pc,spots= #Zpc,dens=yqc.dens,densN=yqc.densN,binsDensN=yqc.densN or 0,lay=yqc.lay,walk=yqc.walk,walkN=yqc.walkN,sep=fqc and(select(2,pcall(fb.laneSep,bb.samples))or yqc.sep)or nil}
fb._masks={}
F.log(1,YMd[3176],string.format(YMd[3718],Vpc,#Zpc,_pc and YMd[3719]or YMd[3720]))
F.saveSoon()
end
bb.helperDealt,bb.helperAt,bb.ownDealt={},0,{}
function bb.sampleHelpers(zqc)
if not zqc and U.now()-bb.helperAt<3 then
return
end
bb.helperAt=U.now()
local Aqc=workspace:FindFirstChild(YMd[3525])
local Bqc={}
for Cqc,Dqc in ipairs(bb.mine or{})do
Bqc[Dqc]=true
local Eqc=Dqc:FindFirstChild(YMd[1841])
local Fqc=Eqc and Eqc:FindFirstChild(YMd[3714])
if Fqc and Eqc:FindFirstChild(YMd[3123])then
local Gqc=bb.ownDealt[Dqc]or{id=Eqc.id.Value,v=0,lvl=0}
Gqc.v=math.max(Gqc.v,Fqc.Value)
Gqc.lvl=math.max(Gqc.lvl,Eqc:FindFirstChild(YMd[1869])and tonumber(Eqc.upgrade.Value)or 0)
bb.ownDealt[Dqc]=Gqc
end
end
for Hqc,Iqc in ipairs(Aqc and Aqc:GetChildren()or{})do
local Jqc=Iqc:FindFirstChild(YMd[1841])
local Kqc=Jqc and Jqc:FindFirstChild(YMd[3530])
local Lqc=Jqc and Jqc:FindFirstChild(YMd[3714])
if Kqc and Lqc and Kqc.Value~=nil and Bqc[Kqc.Value]then
local Mqc=Kqc.Value:FindFirstChild(YMd[1841])
local Nqc=bb.helperDealt[Iqc]or{id=Jqc.id.Value,owner=Mqc and Mqc:FindFirstChild(YMd[3123])and Mqc.id.Value or nil,v=0}
Nqc.v=math.max(Nqc.v,Lqc.Value)
bb.helperDealt[Iqc]=Nqc
end
end
end
function bb.watchHelpers()
local Oqc=workspace:FindFirstChild(YMd[3525])
if not Oqc then
return
end
table.insert(F.conns,Oqc.ChildAdded:Connect(function(Pqc)
task.spawn(function()
local Qqc=Pqc:WaitForChild(YMd[1841],3)
task.wait(0.1)
local Rqc=Qqc and Qqc:FindFirstChild(YMd[3530])
local Sqc=Qqc and Qqc:FindFirstChild(YMd[3714])
if not(Sqc and Rqc and Rqc.Value)then
return
end
local Tqc=Rqc.Value:FindFirstChild(YMd[1841])
local Uqc=Tqc and Tqc:FindFirstChild(YMd[3123])and Tqc.id.Value or nil
if not Uqc then
return
end
local Vqc=false
for Wqc,Xqc in ipairs(bb.mine or{})do
if Xqc==Rqc.Value then
Vqc=true
break
end
end
if not Vqc then
return
end
local function Yqc()
local Zqc=bb.helperDealt[Pqc]or{id=Qqc.id.Value,owner=Uqc,v=0}
Zqc.v=math.max(Zqc.v,Sqc.Value)
bb.helperDealt[Pqc]=Zqc
end
Yqc()
table.insert(F.conns,Sqc.Changed:Connect(Yqc))
end)
end))
end
function bb.damageShares()
pcall(bb.sampleHelpers,true)
local _qc,arc={},0
local function brc(crc,drc)
_qc[crc]=(_qc[crc]or 0)+drc
arc=arc+drc
end
for erc,frc in pairs(bb.ownDealt)do
if not V.isFarm(frc.id)then
brc(frc.id,frc.v)
end
end
local grc=0
for hrc,irc in pairs(bb.helperDealt)do
brc(irc.owner or YMd[2236],irc.v)
grc=grc+1
end
if arc<=0 then
return nil
end
for jrc,krc in pairs(_qc)do
_qc[jrc]=krc/arc
end
return _qc,arc,grc
end
function bb.summonSplit()
local lrc,mrc={},{}
for nrc,orc in pairs(bb.ownDealt)do
lrc[orc.id]=(lrc[orc.id]or 0)+(tonumber(orc.v)or 0)
end
for prc,qrc in pairs(bb.helperDealt)do
if qrc.owner then
mrc[qrc.owner]=(mrc[qrc.owner]or 0)+(tonumber(qrc.v)or 0)
end
end
local rrc={}
for trc,urc in pairs(mrc)do
local vrc=urc+(lrc[trc]or 0)
if vrc>0 then
rrc[trc]={share=urc/vrc,total=vrc}
end
end
return rrc
end
function bb.damageLine()
local wrc,xrc,yrc=bb.damageShares()
if not wrc then
return nil
end
local zrc={}
for Arc,Brc in pairs(wrc)do
table.insert(zrc,{name=Arc==YMd[2236]and YMd[2236]or V.name(Arc),v=Brc})
end
table.sort(zrc,function(Crc,Drc)
return Crc.v>Drc.v
end)
local Erc={}
for Frc,Grc in ipairs(zrc)do
table.insert(Erc,string.format(YMd[2237],Grc.name,math.floor(Grc.v*100+0.5)))
end
local Hrc,Irc=pcall(bb.summonSplit)
local Jrc={}
for Krc,Lrc in pairs(Hrc and Irc or{})do
if Lrc.share>=0.05 and Lrc.total>=0.01*xrc then
table.insert(Jrc,string.format(YMd[2237],V.name(Krc),math.floor(Lrc.share*100+0.5)))
end
end
table.sort(Jrc)
return string.format(YMd[3721],U.fmt(xrc),table.concat(Erc,YMd[2010]),yrc>0 and string.format(YMd[3722],yrc)or YMd[703],#Jrc>0 and(YMd[3723]..table.concat(Jrc,YMd[1890]))or YMd[703])
end
function bb.calMerge(Mrc)
local Nrc=bb.calRun
if not(Nrc and bb.key)then
return
end
local Orc=fb.cal(bb.key)
Orc.n=(tonumber(Orc.n)or 0)+1
local Prc=math.max(0.2,1/Orc.n)
local function Qrc(Rrc)
if#Rrc==0 then
return nil
end
table.sort(Rrc)
