local cAc=(bb.pressure or 0)>=O.safeReach or(bb.depth and bb.depth.leak)
local dAc=kb.weatherStrength(kb.weatherNow())
local eAc=table.find(kb.CARD_PICKS,O.huntCards)and O.huntCards or YMd[2062]
local fAc,gAc,hAc,iAc
