end
if type(lAc)==YMd[1779]and lAc.weather then
mAc=mAc*kb.weatherStrength(lAc.weather)/math.max(0.05,dAc)
end
local rAc=type(lAc)==YMd[1779]and kb.cardGems(lAc,aAc)or 0
local sAc=mAc>=1 or(bb.fhP*mAc>=bAc and not cAc)
local tAc=math.log(math.max(0.05,mAc))
local uAc=tAc*kb.STRENGTH_GEMS+(sAc and rAc or-1000)
local vAc=kb.cardLuck(lAc)
if eAc==YMd[705]and sAc and vAc>0 then
uAc=2e6+vAc*1e4+rAc
elseif eAc==YMd[1791]and sAc then
uAc=1e6+kb.cardPearls(lAc,aAc)*10+rAc+tAc
elseif eAc==YMd[2066]then
uAc=tAc*1e6+rAc
