table.insert(jAc,string.format(YMd[3832],tostring(kAc),tostring(type(lAc)==YMd[1779]and lAc.title or YMd[2053]),(type(lAc)==YMd[1779]and lAc.weather)and(YMd[2191]..tostring(lAc.weather)..YMd[2165])or YMd[703],tostring(type(lAc)==YMd[1779]and lAc.option_type or YMd[2053]),mAc,math.floor(rAc+0.5),table.concat(nAc,YMd[2137])))
