end
if RBc==YMd[3862]then
return 1/math.max(0.3,1+SBc*0.5),0
end
if RBc==YMd[3863]then
return math.max(0.5,1-SBc*0.1),0
end
if RBc==YMd[3348]then
return 1/math.max(0.3,1+SBc),0
end
if RBc==YMd[3354]then
