function bb.learn()
local WBc=bb.calRun and bb.calRun.potBy
if type(WBc)~=YMd[1779]then
return
end
pcall(bb.sampleHelpers,true)
local XBc={}
for YBc,ZBc in pairs(bb.ownDealt or{})do
if not V.isFarm(ZBc.id)then
XBc[ZBc.id]=(XBc[ZBc.id]or 0)+(tonumber(ZBc.v)or 0)
end
end
for _Bc,aCc in pairs(bb.helperDealt or{})do
if aCc.owner and V.SUMMONER[aCc.owner]then
XBc[aCc.owner]=(XBc[aCc.owner]or 0)+(tonumber(aCc.v)or 0)
end
end
local bCc,cCc=0,0
for dCc,eCc in pairs(WBc)do
if eCc>0 then
bCc=bCc+(XBc[dCc]or 0)
cCc=cCc+eCc
end
end
if bCc<=0 or cCc<=0 then
return
end
local fCc=bCc/cCc
bb.lastEff={}
for gCc,hCc in pairs(WBc)do
if hCc>0 and hCc/cCc>0.02 then
local iCc=P.learn[gCc]or{eff=1,n=0,v=3}
if(tonumber(iCc.v)or 0)<3 then
iCc.eff,iCc.v=(tonumber(iCc.eff)or 1)*V.effRescale(gCc),3
end
local jCc=math.max(0.02,0.25*math.sqrt(30/(30+iCc.n)))
local kCc=U.clamp(((XBc[gCc]or 0)/hCc)/fCc,0.2,6)
bb.lastEff[gCc]=math.floor(kCc*1000+0.5)/1000
iCc.eff=iCc.eff+(kCc-iCc.eff)*jCc
iCc.n=iCc.n+1
P.learn[gCc]=iCc
end
end
local lCc=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if lCc and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==YMd[1779]and P.mapLearn or{}
local mCc=type(P.mapLearn[lCc])==YMd[1779]and P.mapLearn[lCc]or{}
for nCc,oCc in pairs(bb.lastEff)do
local pCc=type(mCc[nCc])==YMd[1779]and mCc[nCc]or{eff=oCc,n=0}
local qCc=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(pCc.n)or 0))))
pCc.eff=(tonumber(pCc.n)or 0)==0 and oCc or((tonumber(pCc.eff)or oCc)+(oCc-(tonumber(pCc.eff)or oCc))*qCc)
pCc.n=(tonumber(pCc.n)or 0)+1
mCc[nCc]=pCc
end
mCc._at=os.time()
P.mapLearn[lCc]=mCc
if U.count(P.mapLearn)>80 then
local rCc,sCc
for tCc,uCc in pairs(P.mapLearn)do
if not sCc or(tonumber(uCc._at)or 0)<sCc then
rCc,sCc=tCc,tonumber(uCc._at)or 0
end
end
P.mapLearn[rCc]=nil
end
end
end
function bb.randomTeam()
