end
bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(_Hc,aIc)
local bIc=(aIc.t or 0)-(_Hc.t or 0)
if bIc<bb.BASE_WIN-1 then
return false
end
local cIc=((tonumber(_Hc.base)or 0)-(tonumber(aIc.base)or 0))/bIc
if cIc<=0 or(tonumber(aIc.base)or 0)<=0 then
return false
end
local dIc=aIc.base/cIc
local eIc,fIc=0,0
local gIc,hIc=_Hc.foes or{},aIc.foes or{}
for iIc,jIc in pairs(hIc)do
if jIc.prog>=bb.BASE_END then
eIc=eIc+jIc.hp
local kIc=gIc[iIc]
if kIc then
fIc=fIc+math.max(0,kIc.hp-jIc.hp)
end
end
end
for lIc,mIc in pairs(gIc)do
if mIc.prog>=bb.BASE_END and not hIc[lIc]then
fIc=fIc+mIc.hp
end
end
if eIc<=0 then
return false
end
local nIc=fIc/bIc
local oIc=nIc>0 and eIc/nIc or math.huge
local pIc={baseTime=dIc,loss=cIc,atEnd=eIc,rate=nIc,killTime=oIc}
return dIc<bb.BASE_SOON and oIc>dIc*bb.BASE_MARGIN,pIc
end
