end
local RIc=workspace:FindFirstChild(YMd[3949])and workspace._BASES:FindFirstChild(YMd[3510])
local SIc=RIc and RIc:FindFirstChild(YMd[3716])and RIc.base:FindFirstChild(YMd[3717])
