for ZIc,_Ic in ipairs(bb.enemies or{})do
if _Ic.m then
XIc[_Ic.m]=true
local aJc,bJc=tonumber(_Ic.hp)or 0,tonumber(_Ic.prog)or 0
local cJc=WIc[_Ic.m]
