local hJc=TIc.Health/math.max(1,UIc*(gJc and gJc.MaxHealth or aJc))
local iJc=eJc>0 and fJc/eJc or math.huge
if iJc>hJc*bb.LEAK_MARGIN and(dJc<=bb.LEAK_AHEAD or bb.leakAhead(_Ic)==0)and(not YIc or dJc<YIc.left)then
YIc={left=dJc,arriving=fJc,net=eJc,baseTime=hJc,hp=aJc}
end
end
end
end
end
end
for jJc in pairs(WIc)do
if not XIc[jJc]then
WIc[jJc]=nil
end
end
if PIc then
return YIc~=nil,YIc
end
if not YIc then
