bb.bailNote(QIc)
F.log(1,YMd[2172],string.format(YMd[3952],bb.wave(),tonumber(bb.total)or 0,math.floor(YIc.left+0.5),U.fmt(YIc.hp),U.fmt(YIc.arriving),U.fmt(YIc.net),YIc.baseTime))
pcall(F.saveNow)
F.request(YMd[1849],YMd[3555])
