function mb.evoNeeds(Zrd)
local _rd=mb.K
local asd,bsd,csd,dsd={},{},{},{}
local function esd(fsd)
fsd=tonumber(fsd)or 0
return fsd>=10 and tostring(math.floor(fsd+0.5))or string.format(YMd[4297],fsd)
end
for gsd,hsd in ipairs(Zrd.plans or{})do
local isd,jsd=tonumber(hsd.have)or 0,tonumber(hsd.need)or 0
if hsd.takedown then
table.insert(asd,{mb.cap(tostring(hsd.what or YMd[2376])),string.format(YMd[5022],_rd.comma(isd),_rd.comma(jsd)),p=hsd})
elseif hsd.copies then
dsd[hsd.copies]=true
table.insert(asd,{YMd[5023]..V.name(hsd.copies),string.format(YMd[5024],isd,jsd),p=hsd})
elseif hsd.item then
csd[hsd.item]=true
local ksd=(N.Items[hsd.item]or{}).name or tostring(hsd.item)
local lsd
if hsd.unknown then
lsd=YMd[5025]
elseif hsd.portal then
local msd=W.PORTALS[hsd.portal]
lsd=string.format(YMd[5026],(N.Items[hsd.portal]or{}).name or tostring(hsd.portal),#W.portalsHeld(hsd.portal),msd and(YMd[5027]..W.levelName(msd.from)..YMd[5028])or YMd[703])
elseif hsd.eventShop then
lsd=string.format(YMd[5029],_rd.comma(N.cur(hsd.currency)),_rd.comma(hsd.cost),tostring(hsd.currency))
elseif hsd.shopKey then
lsd=string.format(YMd[5030],_rd.comma(gb.have(hsd.costItem)),_rd.comma((tonumber(hsd.cost)or 0)*(jsd-isd)),(N.Items[hsd.costItem]or{}).name or tostring(hsd.costItem))
else
local nsd=hsd.best or(hsd.levels and hsd.levels[1])
local osd=nsd and(tonumber(nsd.per)or 0)>0 and math.ceil((jsd-isd)/nsd.per)or nil
lsd=nsd and string.format(YMd[5031],W.levelName(nsd.level),esd(nsd.per),osd and string.format(YMd[5032],osd)or YMd[703])or YMd[5025]
end
table.insert(asd,{ksd,string.format(YMd[5033],_rd.comma(isd),_rd.comma(jsd),lsd),p=hsd})
end
end
for psd,qsd in ipairs(Zrd.items or{})do
if not csd[qsd.id]then
table.insert(bsd,string.format(YMd[5034],(N.Items[qsd.id]or{}).name or tostring(qsd.id),_rd.comma(gb.have(qsd.id)),_rd.comma(qsd.amount)))
end
end
for rsd,ssd in ipairs(Zrd.eats or{})do
if not dsd[ssd.id]then
table.insert(bsd,string.format(YMd[5035],V.name(ssd.id),ssd.amount,ssd.amount))
end
end
local tsd=asd[1]
return asd,bsd,tsd and(tsd[1]..YMd[2125]..(tsd[2]:match(YMd[5036])or tsd[2]))or YMd[5037]
end
function mb.evoProgress(usd)
if usd.ready then
return 1
end
local vsd,wsd,xsd=0,0,{}
for ysd,zsd in ipairs(usd.plans or{})do
local Asd=tonumber(zsd.need)or 0
if zsd.item then
xsd[zsd.item]=true
end
if Asd>0 then
vsd=vsd+math.min(1,(tonumber(zsd.have)or 0)/Asd)
wsd=wsd+1
end
end
for Bsd,Csd in ipairs(usd.items or{})do
if not xsd[Csd.id]then
vsd=vsd+1
wsd=wsd+1
end
end
return wsd>0 and vsd/wsd or 0
end
function mb.pickFor(Dsd)
Dsd=tostring(Dsd or YMd[703])
if Dsd==YMd[703]then
return nil
end
local Esd=Dsd:gsub(YMd[2923],YMd[2924])
for Fsd,Gsd in ipairs({{YMd[4509],YMd[4504],YMd[4509]},{YMd[1818],YMd[4502],YMd[1795]},{YMd[1798],YMd[4505],YMd[1798]},{YMd[1817],YMd[4503],YMd[1817]}})do
local Hsd,Isd=pcall(mb.modeOptions,Gsd[1])
local Jsd
for Ksd,Lsd in ipairs(Hsd and Isd or{})do
local Msd=tostring(Lsd.value)
if Msd==YMd[2200]..Dsd or Msd==YMd[1953]..Dsd or Msd:find(YMd[5038]..Esd..YMd[1905])then
if not Jsd or Msd:find(YMd[5039])then
Jsd=Lsd
end
end
end
if Jsd then
return{cfgKey=Gsd[2],value=Jsd.value,kind=Gsd[1],kindKey=Gsd[3],name=tostring(Jsd.text)}
end
end
end
function mb.portalFor(Nsd)
for Osd,Psd in ipairs(W.portalKinds())do
if table.find(Psd.levels or{},Nsd)then
if#W.portalsHeld(Psd.pid)>0 then
return{cfgKey=YMd[4506],value=Psd.pid,kind=YMd[1964],kindKey=YMd[1971],name=tostring(Psd.name)}
end
local Qsd=W.PORTALS[Psd.pid]
local Rsd=Qsd and Qsd.from and mb.pickFor(Qsd.from)
if Rsd then
return Rsd
end
end
end
end
function mb.evoMap(Ssd)
local Tsd=mb._evoMap
if Tsd and Tsd.uuid==Ssd.uuid and U.now()-Tsd.at<30 then
return Tsd.m
end
local Usd
for Vsd,Wsd in ipairs(Ssd.plans or{})do
if Usd then
break
end
if Wsd.portal then
if#W.portalsHeld(Wsd.portal)>0 then
Usd={cfgKey=YMd[4506],value=Wsd.portal,kind=YMd[1964],kindKey=YMd[1971],name=(N.Items[Wsd.portal]or{}).name or tostring(Wsd.portal)}
end
elseif Wsd.item and not Wsd.unknown and not Wsd.eventShop then
local Xsd=Wsd.best or(Wsd.levels and Wsd.levels[1])
if Xsd and Xsd.level then
Usd=mb.pickFor(Xsd.level)or mb.portalFor(Xsd.level)
end
end
end
mb._evoMap={uuid=Ssd.uuid,at=U.now(),m=Usd}
return Usd
end
function mb.selectMap(Ysd)
if not Ysd then
return
end
O[Ysd.cfgKey]=Ysd.value
for Zsd,_sd in ipairs(mb.modeKinds())do
if _sd.key==Ysd.kindKey then
for atd,btd in ipairs(_sd.allow)do
O[btd]=true
end
end
end
F.saveSoon()
W.lastScored=nil
ab.last.pick=nil
pcall(function()
mb.UI[Ysd.cfgKey..YMd[4639]].Refresh(mb.modeOptions(Ysd.kind),Ysd.value)
end)
pcall(function()
mb.modeSw[Ysd.kindKey].Set(true,true)
end)
pcall(mb.modeDeps,Ysd.kindKey)
mb._evoMap=nil
F.log(1,YMd[2128],string.format(YMd[5040],Ysd.name,mb.KIND_NAMES[Ysd.kind]or Ysd.kind))
mb.notify(YMd[5041],string.format(YMd[5042],Ysd.name,mb.KIND_NAMES[Ysd.kind]or Ysd.kind),YMd[2423])
end
function mb.evoTarget()
local ctd=mb.focusNow()
local dtd=ctd~=YMd[703]and ctd or((P.train.on and P.train.on.uuid)or((P.goals or{})[1]and P.goals[1].uuid))
if not dtd then
return nil,ctd~=YMd[703]
end
for etd,ftd in ipairs(P.goals or{})do
if ftd.uuid==dtd then
return ftd,ctd~=YMd[703]
end
end
for gtd,htd in ipairs(P.goalsTop or{})do
if htd.uuid==dtd then
return htd,ctd~=YMd[703]
end
end
return nil,ctd~=YMd[703]
