local pwd=P.snipe or{}
local qwd=tostring(O.snipeUnit or YMd[703])
local rwd={id=qwd,name=qwd~=YMd[703]and V.name(qwd)or nil,turnAt=ab.snipeTurnAfter(os.time()),clock=pwd.clock~=nil,lookAt=pwd.lookAt,pulls=tonumber(pwd.pulls)or 0}
if qwd==YMd[703]then
rwd.state,rwd.line,rwd.short=YMd[2084],YMd[5208],YMd[5209]
return rwd
end
if ab.snipeHas(qwd)then
rwd.state,rwd.line,rwd.short=YMd[5210],YMd[2821]..rwd.name..YMd[5211],YMd[2806]..rwd.name
return rwd
end
rwd.stale=ab.snipeStale()
rwd.bid=ab.snipeWhere(qwd)
local swd=rwd.bid and ab.snipeCost(rwd.bid)or nil
if swd then
rwd.bc=swd
rwd.have,rwd.keep,rwd.cost10=tonumber(swd.have())or 0,tonumber(swd.keep)or 0,(tonumber(swd.cost)or 0)*10
rwd.avail=math.max(0,rwd.have-rwd.keep)
end
local twd=mb.sumBack(YMd[2533])
local function uwd(vwd,wwd)
rwd.state,rwd.line,rwd.short=YMd[5212],vwd,YMd[5213]..wwd
end
if not O.snipeOn then
rwd.state,rwd.line,rwd.short=YMd[706],YMd[5214]..rwd.name..YMd[2085],YMd[706]
elseif P.pauseAll then
rwd.state,rwd.line,rwd.short=YMd[2943],YMd[5215],YMd[2943]
elseif not pwd.lookAt then
uwd(YMd[5216],YMd[5217])
elseif rwd.stale then
uwd(YMd[5218],YMd[5219])
elseif not rwd.bid then
uwd(string.format(YMd[5220],rwd.name,os.date(YMd[2565],rwd.turnAt)),string.format(YMd[5221],rwd.name,os.date(YMd[2565],rwd.turnAt)))
elseif not swd then
uwd(YMd[5222],YMd[5223])
elseif not ab.watchRoom()then
uwd(YMd[5224],YMd[5225])
elseif twd then
uwd(string.format(YMd[5226],os.date(YMd[2565],twd)),YMd[5227])
elseif rwd.have-rwd.cost10<rwd.keep then
uwd(string.format(YMd[5228],owd.comma(rwd.have),swd.name,owd.comma(rwd.cost10),owd.comma(rwd.keep)),swd.name..YMd[2851])
else
rwd.state=YMd[5229]
rwd.short=string.format(YMd[5230],rwd.name,swd.label,swd.name)
rwd.line=F.where==YMd[1849]and string.format(YMd[5231],swd.label,swd.name)or string.format(YMd[5232],swd.label,swd.name)
end
return rwd
end
function mb.sumAuto()
