if zwd then
ywd.bc,ywd.key=zwd,zwd.floor
ywd.have,ywd.keep,ywd.cost10=tonumber(zwd.have())or 0,tonumber(O[zwd.floor])or 0,(tonumber(zwd.cost)or 0)*10
ywd.avail=math.max(0,ywd.have-ywd.keep)
