local Awd=mb.sumBack(YMd[1864])
local function Bwd(Cwd,Dwd)
ywd.state,ywd.line,ywd.short=YMd[5212],Cwd,YMd[5213]..Dwd
end
if ywd.banner==YMd[703]then
ywd.state,ywd.line,ywd.short=YMd[2084],YMd[5233],YMd[5234]
elseif not zwd then
ywd.state,ywd.line,ywd.short=YMd[2084],YMd[5235],YMd[5236]
elseif not O.autoSummon then
ywd.state,ywd.line,ywd.short=YMd[706],string.format(YMd[5237],ywd.label,zwd.name),YMd[706]
elseif P.pauseAll then
ywd.state,ywd.line,ywd.short=YMd[2943],YMd[5215],YMd[2943]
elseif not ab.watchRoom()then
Bwd(YMd[5238],YMd[5225])
elseif Awd then
Bwd(string.format(YMd[5226],os.date(YMd[2565],Awd)),YMd[5227])
elseif ywd.have-ywd.cost10<ywd.keep then
Bwd(string.format(YMd[5228],xwd.comma(ywd.have),zwd.name,xwd.comma(ywd.cost10),xwd.comma(ywd.keep)),zwd.name..YMd[2851])
else
ywd.state=YMd[5229]
ywd.short=string.format(YMd[5239],ywd.label,zwd.name)
ywd.line=F.where==YMd[1849]and string.format(YMd[5240],ywd.label,zwd.name,tonumber(O.summonsPerVisit)or 20)or string.format(YMd[5241],ywd.label,zwd.name)
end
return ywd
end
function mb.sumPart(Ewd)
local Fwd=tostring(Q.Summon or YMd[703])
for Gwd in(Fwd..YMd[2010]):gmatch(YMd[4720])do
if Gwd:lower():sub(1,#Ewd)==Ewd:lower()then
return(Gwd:sub(#Ewd+1):gsub(YMd[5242],YMd[703]))
end
end
end
function mb.sumGot(Hwd,Iwd)
local Jwd,Kwd,Lwd={},{},{}
for Mwd,Nwd in ipairs(Iwd or{})do
local Owd=tostring((N.Units[Nwd]or{}).rarity or YMd[2074])
Kwd[Owd]=(Kwd[Owd]or 0)+1
table.insert(Jwd,V.name(Nwd)..YMd[2191]..Owd..YMd[2165])
end
for Pwd,Qwd in ipairs(mb.RARITY_ORDER)do
Lwd[Qwd]=true
local Rwd=(tonumber((Hwd or{})[Qwd])or 0)-(Kwd[Qwd]or 0)
if Rwd>0 then
table.insert(Jwd,Rwd..YMd[1952]..Qwd)
end
end
for Swd,Twd in pairs(Hwd or{})do
if not Lwd[Swd]and(tonumber(Twd)or 0)>0 then
table.insert(Jwd,Twd..YMd[1952]..tostring(Swd))
end
end
return mb.andList(Jwd)
end
function mb.sumRecent()
local Uwd=mb.K
local Vwd=P.pulls or{}
local Wwd=os.time()-86400
local Xwd,Ywd,Zwd,_wd,axd=0,{},{},{},{}
local function bxd(cxd,dxd)
cxd=tostring(cxd or YMd[2053])
if not Ywd[cxd]then
table.insert(Zwd,cxd)
end
Ywd[cxd]=(Ywd[cxd]or 0)+(tonumber(dxd)or 0)
end
for exd,fxd in ipairs(Vwd)do
if(tonumber(fxd.at)or 0)>=Wwd then
Xwd=Xwd+(tonumber(fxd.n)or 10)
bxd(fxd.cur,fxd.cost)
for gxd,hxd in pairs(fxd.got or{})do
_wd[gxd]=(_wd[gxd]or 0)+(tonumber(hxd)or 0)
end
for ixd,jxd in ipairs(fxd.best or{})do
table.insert(axd,jxd)
end
end
end
if#Vwd==0 then
for kxd,lxd in ipairs(P.spend or{})do
if(tonumber(lxd.at)or 0)>=Wwd and tostring(lxd.what):find(YMd[1863])then
Xwd=Xwd+10
bxd(lxd.cur,lxd.cost)
end
end
end
local mxd
if Xwd==0 then
mxd= #Vwd==0 and YMd[5243]or YMd[5244]
else
local nxd={}
for oxd,pxd in ipairs(Zwd)do
table.insert(nxd,Uwd.comma(Ywd[pxd])..YMd[1952]..pxd)
end
mxd=string.format(YMd[5245],Uwd.comma(Xwd),mb.andList(nxd))
local qxd=mb.sumGot(_wd,axd)
if qxd~=YMd[703]then
mxd=mxd..YMd[5246]..qxd..YMd[2085]
end
end
local rxd={}
for sxd=1,math.min(20,#Vwd)do
local txd=Vwd[sxd]
local uxd=mb.sumGot(txd.got,txd.best)
table.insert(rxd,string.format(YMd[5247],os.date(YMd[1880],tonumber(txd.at)or os.time()),ab.BANNER_NAME[txd.banner]or tostring(txd.banner),tostring(txd.rule or YMd[1864]),Uwd.comma(tonumber(txd.cost)or 0),tostring(txd.cur or YMd[703]),uxd~=YMd[703]and(YMd[2125]..uxd)or YMd[703]))
end
return mxd,#rxd>0 and table.concat(rxd,YMd[1789])or YMd[5140]
end
