function mb.abilityWait(Kyd,Lyd)
Lyd=tonumber(Lyd)or tonumber(O.abilityHold)or 20
return math.min(Lyd*math.max(1,Kyd/60),Kyd*0.3)
end
function mb.secs(Myd)
Myd=math.floor((tonumber(Myd)or 0)+0.5)
if Myd<60 then
return Myd..YMd[4758]
end
local Nyd,Oyd=math.floor(Myd/60),Myd%60
return Oyd>0 and string.format(YMd[5328],Nyd,Oyd)or string.format(YMd[2159],Nyd)
end
